INSERT IGNORE INTO reporting_queries (slug, name, description, category, sql_query, is_system)
VALUES
('agent-conversations-by-user-30-days-company-scoped', 'AI Agent: Conversations by User (Last 30 Days) (Company Scoped)', 'AI agent conversations started in the last 30 days per user, with total turns and the last conversation time. Company scoped: limited to the company the report is run for.', 'AI', 'SELECT us.email AS user_email, TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS user_name, COUNT(DISTINCT ac.id) AS conversations, COUNT(t.id) AS turns, MAX(ac.updated_at) AS last_activity_at FROM agent_conversations ac JOIN users us ON us.id = ac.user_id LEFT JOIN agent_conversation_turns t ON t.conversation_id = ac.id WHERE ac.company_id = {{current.company}} AND ac.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY ac.user_id, us.email, us.first_name, us.last_name ORDER BY conversations DESC', 1),
('assets-by-asset-type-company-scoped', 'Assets: Count by Asset Type and Company (Company Scoped)', 'Active assets per company and asset type (as used by the network map and rack views), with how many were classified automatically. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.name AS company, COALESCE(a.asset_type, ''unclassified'') AS asset_type, COUNT(*) AS assets, SUM(CASE WHEN a.asset_type_source = ''auto'' THEN 1 ELSE 0 END) AS auto_classified FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL GROUP BY a.company_id, c.name, a.asset_type ORDER BY company, assets DESC', 1),
('assets-by-status-and-type-company-scoped', 'Assets: Status by Type (Company Scoped)', 'Asset counts broken down by type and status to support lifecycle management and audits. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT COALESCE(NULLIF(TRIM(a.type), ''''), ''(unspecified)'') AS asset_type, COALESCE(NULLIF(TRIM(a.status), ''''), ''(unspecified)'') AS asset_status, COUNT(*) AS asset_count FROM assets a WHERE a.company_id = {{current.company}} GROUP BY COALESCE(NULLIF(TRIM(a.type), ''''), ''(unspecified)''), COALESCE(NULLIF(TRIM(a.status), ''''), ''(unspecified)'') ORDER BY asset_count DESC, asset_type ASC, asset_status ASC', 1),
('assets-by-tag-company-scoped', 'Assets: Count by Tag (Company Scoped)', 'Tags with the number of active assets carrying them, split into manually applied and automatically applied. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT tg.name AS tag, tg.slug, COUNT(at.asset_id) AS assets, SUM(CASE WHEN at.source = ''manual'' THEN 1 ELSE 0 END) AS manual, SUM(CASE WHEN at.source <> ''manual'' THEN 1 ELSE 0 END) AS automatic, COUNT(DISTINCT a.company_id) AS companies FROM tags tg JOIN asset_tags at ON at.tag_id = tg.id JOIN assets a ON a.id = at.asset_id AND a.archived_at IS NULL WHERE a.company_id = {{current.company}} GROUP BY tg.id, tg.name, tg.slug ORDER BY assets DESC, tg.name', 1),
('assets-out-of-warranty-company-scoped', 'Assets: Out of Warranty (Company Scoped)', 'Active assets whose warranty has already ended, longest expired first. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.name AS company, a.name AS asset, a.asset_type, a.serial_number, a.warranty_end_date, DATEDIFF(CURRENT_DATE, a.warranty_end_date) AS days_expired, a.warranty_source, a.last_sync FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL AND a.warranty_end_date < CURRENT_DATE ORDER BY a.warranty_end_date ASC', 1),
('assets-warranty-expiring-next-90-days-company-scoped', 'Assets: Warranties Expiring in the Next 90 Days (Company Scoped)', 'Active assets whose warranty ends in the next 90 days, with the warranty source and when it was last looked up. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.name AS company, a.name AS asset, a.asset_type, a.serial_number, a.warranty_start_date, a.warranty_end_date, DATEDIFF(a.warranty_end_date, CURRENT_DATE) AS days_remaining, a.warranty_status, a.warranty_source, a.warranty_checked_at FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL AND a.warranty_end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL 90 DAY ORDER BY a.warranty_end_date ASC', 1),
('assets-warranty-lookup-status-company-scoped', 'Assets: Warranty Lookup Coverage by Company (Company Scoped)', 'Per company, active assets with a warranty found, not found, unsupported, errored or never looked up. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.name AS company, COUNT(*) AS assets, SUM(CASE WHEN a.warranty_lookup_status = ''found'' THEN 1 ELSE 0 END) AS found, SUM(CASE WHEN a.warranty_lookup_status = ''not_found'' THEN 1 ELSE 0 END) AS not_found, SUM(CASE WHEN a.warranty_lookup_status = ''unsupported'' THEN 1 ELSE 0 END) AS unsupported, SUM(CASE WHEN a.warranty_lookup_status = ''error'' THEN 1 ELSE 0 END) AS errors, SUM(CASE WHEN a.warranty_lookup_status IS NULL THEN 1 ELSE 0 END) AS never_checked, MAX(a.warranty_checked_at) AS last_checked_at FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL GROUP BY a.company_id, c.name ORDER BY company', 1),
('assets-without-rmm-agent-company-scoped', 'Assets: Workstations and Servers Without RMM (Company Scoped)', 'Active assets classified as workstations, laptops, thin clients, servers, hypervisors or virtual machines that have no active RMM agent. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.name AS company, a.name AS asset, a.asset_type, a.os_name, a.last_user, a.last_sync FROM assets a LEFT JOIN companies c ON c.id = a.company_id WHERE a.company_id = {{current.company}} AND a.archived_at IS NULL AND a.asset_type IN (''workstation'', ''laptop'', ''thin_client'', ''server'', ''hypervisor'', ''virtual_machine'') AND NOT EXISTS (SELECT 1 FROM rmm_agents ag WHERE ag.asset_id = a.id AND ag.status = ''active'') ORDER BY company, asset', 1),
('count-of-assets-per-company-company-scoped', 'Count of Assets Per Company (Company Scoped)', 'Number of assets registered in MyPortal for each company, highest count first. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.id AS company_id, c.name AS company, COUNT(a.id) AS asset_count FROM companies c LEFT JOIN assets a ON a.company_id = c.id WHERE c.id = {{current.company}} GROUP BY c.id, c.name ORDER BY asset_count DESC, c.name ASC', 1),
('dashboard-global-assets-by-company-company-scoped', 'Dashboard - Global assets by company (Company Scoped)', 'Dashboard panel: Global assets by company. Company scoped: limited to the company the report is run for.', 'Assets', 'SELECT c.name AS X, COUNT(a.id) AS Y FROM companies c LEFT JOIN assets a ON a.company_id=c.id WHERE c.id = {{current.company}} GROUP BY c.id,c.name ORDER BY Y DESC', 1),
('business-hours-closures-upcoming-company-scoped', 'Business Hours: Upcoming Closures (Company Scoped)', 'Global and company-specific business hours closures from today onwards. Company scoped: limited to the company the report is run for.', 'Automation and Integrations', 'SELECT bc.closure_date, bc.name, COALESCE(c.name, ''All companies'') AS company, DAYNAME(bc.closure_date) AS weekday FROM business_hours_closures bc LEFT JOIN companies c ON c.id = bc.company_id WHERE COALESCE(bc.company_id, {{current.company}}) = {{current.company}} AND bc.closure_date >= CURRENT_DATE ORDER BY bc.closure_date, company', 1),
('business-hours-deferred-automations-company-scoped', 'Automations: Deferred by Business Hours (Company Scoped)', 'Automation runs deferred until business hours, with status, when they are due and any error, newest first. Company scoped: limited to the company the report is run for.', 'Automation and Integrations', 'SELECT au.name AS automation, d.event_name, c.name AS company, t.ticket_number, d.status, d.run_after, d.processed_at, d.error_message, d.created_at FROM automation_deferred_runs d LEFT JOIN automations au ON au.id = d.automation_id LEFT JOIN companies c ON c.id = d.company_id LEFT JOIN tickets t ON t.id = d.ticket_id WHERE d.company_id = {{current.company}} ORDER BY FIELD(d.status, ''pending'', ''failed''), d.run_after DESC', 1),
('dashboard-notifications-company-scoped', 'Dashboard - Notifications (Company Scoped)', 'Dashboard panel: Notifications. Company scoped: limited to the company the report is run for.', 'Automation and Integrations', 'SELECT n.id, n.event_type FROM notifications n JOIN users u ON u.id = n.user_id WHERE u.company_id = {{current.company}} AND n.user_id IS NOT NULL', 1),
('stat-strip-service-status-catalogue-company-scoped', 'Stat Strip - Admin - Service Status Catalogue (Company Scoped)', 'All active services by displayed service status on the administration catalogue. Company scoped: limited to the company the report is run for.', 'Automation and Integrations', 'SELECT COUNT(*) AS total, SUM(CASE WHEN status = ''operational'' THEN 1 ELSE 0 END) AS operational, SUM(CASE WHEN status = ''maintenance'' THEN 1 ELSE 0 END) AS maintenance, SUM(CASE WHEN status = ''degraded'' THEN 1 ELSE 0 END) AS degraded, SUM(CASE WHEN status = ''partial_outage'' THEN 1 ELSE 0 END) AS partial_outage, SUM(CASE WHEN status = ''outage'' THEN 1 ELSE 0 END) AS outage FROM service_status_services WHERE {{current.company}} IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM service_status_service_companies ssc WHERE ssc.service_id = service_status_services.id) OR EXISTS (SELECT 1 FROM service_status_service_companies ssc WHERE ssc.service_id = service_status_services.id AND ssc.company_id = {{current.company}})) AND is_active = 1', 1),
('backup-jobs-health-last-30-days-company-scoped', 'Backups: Job Health (Last 30 Days) (Company Scoped)', 'Per-backup-job status summary over the last 30 days, including pass/fail/warn counts and latest report time. Company scoped: limited to the company the report is run for.', 'Backups and Continuity', 'SELECT c.name AS company, bj.name AS backup_job, COUNT(*) AS total_events, SUM(CASE WHEN bje.status = ''pass'' THEN 1 ELSE 0 END) AS pass_events, SUM(CASE WHEN bje.status = ''fail'' THEN 1 ELSE 0 END) AS fail_events, SUM(CASE WHEN bje.status = ''warn'' THEN 1 ELSE 0 END) AS warn_events, MAX(bje.reported_at) AS last_reported_at FROM backup_job_events bje JOIN backup_jobs bj ON bj.id = bje.backup_job_id JOIN companies c ON c.id = bj.company_id WHERE bj.company_id = {{current.company}} AND bje.event_date >= (CURRENT_DATE - INTERVAL 30 DAY) GROUP BY c.id, c.name, bj.id, bj.name ORDER BY fail_events DESC, warn_events DESC, company ASC, backup_job ASC', 1),
('backup-register-company-scoped', 'Backups: Backup Register (Company Scoped)', 'Documented backups per company with backup application, frequency, linked monitored job and its latest status. Company scoped: limited to the company the report is run for.', 'Backups and Continuity', 'SELECT c.name AS company, br.name AS backup, ba.name AS backup_app, br.frequency, bj.name AS monitored_job, CASE WHEN br.backup_job_id IS NULL THEN ''not linked'' ELSE ''linked'' END AS monitoring, (SELECT e.status FROM backup_job_events e WHERE e.backup_job_id = br.backup_job_id ORDER BY e.event_date DESC, e.id DESC LIMIT 1) AS latest_job_status, br.updated_at FROM backup_register br LEFT JOIN companies c ON c.id = br.company_id LEFT JOIN backup_apps ba ON ba.id = br.backup_app_id LEFT JOIN backup_jobs bj ON bj.id = br.backup_job_id WHERE br.company_id = {{current.company}} ORDER BY company, backup', 1),
('billable-amount-per-company-current-month-company-scoped', 'Billable Amount Per Company – Current Month (Company Scoped)', 'Total billed amount per company for the current calendar month, based on time entries recorded in ticket_billed_time_entries. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT c.name AS company, COUNT(DISTINCT bte.ticket_id) AS tickets_billed, SUM(bte.minutes_billed) AS total_minutes_billed, ROUND(SUM(bte.minutes_billed * COALESCE(lt.rate, 0) / 60.0), 2) AS total_amount_billed FROM ticket_billed_time_entries bte JOIN tickets t ON t.id = bte.ticket_id JOIN companies c ON c.id = t.company_id LEFT JOIN ticket_labour_types lt ON lt.id = bte.labour_type_id WHERE t.company_id = {{current.company}} AND YEAR(bte.billed_at) = YEAR(CURRENT_DATE) AND MONTH(bte.billed_at) = MONTH(CURRENT_DATE) GROUP BY c.id, c.name ORDER BY total_amount_billed DESC, c.name ASC', 1),
('billable-amount-per-company-previous-month-company-scoped', 'Billable Amount Per Company – Previous Month (Company Scoped)', 'Total billed amount per company for the previous calendar month, based on time entries recorded in ticket_billed_time_entries. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT c.name AS company, COUNT(DISTINCT bte.ticket_id) AS tickets_billed, SUM(bte.minutes_billed) AS total_minutes_billed, ROUND(SUM(bte.minutes_billed * COALESCE(lt.rate, 0) / 60.0), 2) AS total_amount_billed FROM ticket_billed_time_entries bte JOIN tickets t ON t.id = bte.ticket_id JOIN companies c ON c.id = t.company_id LEFT JOIN ticket_labour_types lt ON lt.id = bte.labour_type_id WHERE t.company_id = {{current.company}} AND YEAR(bte.billed_at) = YEAR(DATE_SUB(CURRENT_DATE, INTERVAL 1 MONTH)) AND MONTH(bte.billed_at) = MONTH(DATE_SUB(CURRENT_DATE, INTERVAL 1 MONTH)) GROUP BY c.id, c.name ORDER BY total_amount_billed DESC, c.name ASC', 1),
('billed-tickets-company-scoped', 'Billed Tickets (Company Scoped)', 'Tickets that have been billed via Xero, showing the invoice number, total minutes billed, and calculated amount billed per ticket. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT t.id AS ticket_id, c.name AS company, t.subject, t.status, t.xero_invoice_number, COALESCE(SUM(bte.minutes_billed), 0) AS total_minutes_billed, ROUND(COALESCE(SUM(bte.minutes_billed * COALESCE(lt.rate, 0) / 60.0), 0), 2) AS total_amount_billed, t.billed_at, t.closed_at FROM tickets t LEFT JOIN companies c ON c.id = t.company_id LEFT JOIN ticket_billed_time_entries bte ON bte.ticket_id = t.id LEFT JOIN ticket_labour_types lt ON lt.id = bte.labour_type_id WHERE t.company_id = {{current.company}} AND t.xero_invoice_number IS NOT NULL GROUP BY t.id, c.name, t.subject, t.status, t.xero_invoice_number, t.billed_at, t.closed_at ORDER BY t.billed_at DESC, t.id DESC', 1),
('invoices-status-and-overdue-by-company-company-scoped', 'Invoices: Status and Overdue by Company (Company Scoped)', 'Invoice totals and overdue counts by company. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT c.name AS company, COALESCE(i.status, ''(unspecified)'') AS invoice_status, COUNT(*) AS invoice_count, ROUND(SUM(i.amount), 2) AS total_amount, SUM(CASE WHEN i.due_date IS NOT NULL AND i.due_date < CURRENT_DATE THEN 1 ELSE 0 END) AS overdue_count FROM invoices i JOIN companies c ON c.id = i.company_id WHERE i.company_id = {{current.company}} GROUP BY c.id, c.name, COALESCE(i.status, ''(unspecified)'') ORDER BY overdue_count DESC, total_amount DESC, company ASC', 1),
('revenue-leakage-unbilled-time-company-scoped', 'Revenue Leakage - Unbilled Time (Company Scoped)', 'Remaining unbilled ticket time by age, company, and technician so operators can follow up on billing leakage. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT c.id AS company_id, COALESCE(c.name, ''(no company)'') AS company, COALESCE(NULLIF(TRIM(CONCAT(COALESCE(u.first_name, ''''), '' '', COALESCE(u.last_name, ''''))), ''''), NULLIF(TRIM(u.email), ''''), ''(unassigned)'') AS technician, CASE WHEN TIMESTAMPDIFF(DAY, COALESCE(t.closed_at, t.created_at), CURRENT_TIMESTAMP) >= 30 THEN ''30+ days'' WHEN TIMESTAMPDIFF(DAY, COALESCE(t.closed_at, t.created_at), CURRENT_TIMESTAMP) >= 14 THEN ''14-29 days'' WHEN TIMESTAMPDIFF(DAY, COALESCE(t.closed_at, t.created_at), CURRENT_TIMESTAMP) >= 7 THEN ''7-13 days'' ELSE ''0-6 days'' END AS age_bucket, COUNT(DISTINCT t.id) AS ticket_count, COUNT(DISTINCT tr.id) AS reply_count, SUM(tr.minutes_spent - COALESCE(billed.billed_minutes, 0)) AS unbilled_minutes, ROUND(SUM((tr.minutes_spent - COALESCE(billed.billed_minutes, 0)) * COALESCE(lt.rate, 0)), 2) AS unbilled_amount FROM ticket_replies tr JOIN tickets t ON t.id = tr.ticket_id LEFT JOIN companies c ON c.id = t.company_id LEFT JOIN users u ON u.id = tr.author_id LEFT JOIN ticket_labour_types lt ON lt.id = tr.labour_type_id LEFT JOIN (SELECT reply_id, SUM(minutes_billed) AS billed_minutes FROM ticket_billed_time_entries GROUP BY reply_id) billed ON billed.reply_id = tr.id WHERE t.company_id = {{current.company}} AND tr.is_billable = 1 AND tr.minutes_spent IS NOT NULL AND tr.minutes_spent > COALESCE(billed.billed_minutes, 0) GROUP BY c.id, c.name, technician, age_bucket ORDER BY unbilled_amount DESC, unbilled_minutes DESC, company ASC, technician ASC', 1),
('tech-billable-vs-non-billable-per-day-company-scoped', 'Tech Billable vs Non-Billable Time Per Day (Company Scoped)', 'For each technician and day in the last 30 days, total billable and non-billable minutes recorded on ticket replies. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT DATE(tr.created_at) AS day, COALESCE(u.email, ''(unassigned)'') AS technician, SUM(CASE WHEN tr.is_billable = 1 THEN COALESCE(tr.minutes_spent, 0) ELSE 0 END) AS billable_minutes, SUM(CASE WHEN tr.is_billable = 0 THEN COALESCE(tr.minutes_spent, 0) ELSE 0 END) AS non_billable_minutes FROM ticket_replies tr JOIN tickets t ON t.id = tr.ticket_id LEFT JOIN users u ON u.id = tr.author_id WHERE t.company_id = {{current.company}} AND tr.created_at >= (CURRENT_DATE - INTERVAL 30 DAY) AND COALESCE(tr.minutes_spent, 0) > 0 GROUP BY DATE(tr.created_at), u.email ORDER BY day DESC, technician ASC', 1),
('unbilled-tickets-company-scoped', 'Unbilled Tickets (Company Scoped)', 'Closed tickets that have billable time entries but have not yet been linked to a Xero invoice. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT t.id AS ticket_id, c.name AS company, t.subject, t.status, COALESCE(SUM(CASE WHEN tr.is_billable = 1 THEN tr.minutes_spent ELSE 0 END), 0) AS billable_minutes, t.closed_at, t.created_at FROM tickets t LEFT JOIN companies c ON c.id = t.company_id LEFT JOIN ticket_replies tr ON tr.ticket_id = t.id WHERE t.company_id = {{current.company}} AND t.xero_invoice_number IS NULL GROUP BY t.id, c.name, t.subject, t.status, t.closed_at, t.created_at HAVING billable_minutes > 0 ORDER BY t.closed_at DESC, t.id DESC', 1),
('unbilled-tickets-by-company-company-scoped', 'Unbilled Tickets By Company (Company Scoped)', 'Unbilled billable ticket time by company and labour type, including the number of tickets represented in each total. Company scoped: limited to the company the report is run for.', 'Billing', 'SELECT c.id AS company_id, COALESCE(c.name, ''(no company)'') AS company, COALESCE(NULLIF(TRIM(lt.name), ''''), ''(unspecified)'') AS labour_type, COUNT(DISTINCT t.id) AS ticket_count, SUM(tr.minutes_spent) AS billable_minutes FROM ticket_replies tr JOIN tickets t ON t.id = tr.ticket_id LEFT JOIN companies c ON c.id = t.company_id LEFT JOIN ticket_labour_types lt ON lt.id = tr.labour_type_id WHERE t.company_id = {{current.company}} AND tr.is_billable = 1 AND tr.minutes_spent IS NOT NULL AND tr.minutes_spent > 0 AND NOT EXISTS (SELECT 1 FROM ticket_billed_time_entries bte WHERE bte.reply_id = tr.id) GROUP BY c.id, c.name, lt.id, lt.name ORDER BY company ASC, labour_type ASC', 1),
('chat-room-activity-last-14-days-company-scoped', 'Chats: Room Activity (Last 14 Days) (Company Scoped)', 'Open and closed chat room activity over the last 14 days with message counts and last message timestamp. Company scoped: limited to the company the report is run for.', 'Calls and Chat', 'SELECT c.name AS company, cr.status, COUNT(DISTINCT cr.id) AS room_count, COUNT(cm.id) AS message_count, MAX(cm.sent_at) AS last_message_at FROM chat_rooms cr JOIN companies c ON c.id = cr.company_id LEFT JOIN chat_messages cm ON cm.room_id = cr.id AND cm.sent_at >= (CURRENT_DATE - INTERVAL 14 DAY) WHERE cr.company_id = {{current.company}} GROUP BY c.id, c.name, cr.status ORDER BY message_count DESC, company ASC, cr.status ASC', 1),
('client-onboarding-pipeline-company-scoped', 'Client Onboarding: Invitation Pipeline (Company Scoped)', 'Client onboarding invitations with status, recipient, expiry, submission and approval times and the resulting company. Company scoped: limited to the company the report is run for.', 'Companies and Onboarding', 'SELECT co.client_name, co.contact_name, co.recipient_email, co.status, co.created_at, co.expires_at, co.submitted_at, co.approved_at, TIMESTAMPDIFF(HOUR, co.created_at, co.submitted_at) AS hours_to_submit, c.name AS company, t.ticket_number, co.error_message FROM client_onboardings co LEFT JOIN companies c ON c.id = co.company_id LEFT JOIN tickets t ON t.id = co.ticket_id WHERE co.company_id = {{current.company}} ORDER BY FIELD(co.status, ''submitted'', ''pending'', ''processing'', ''failed'', ''approved'', ''declined'', ''revoked''), co.created_at DESC', 1),
('companies-pending-approval-company-scoped', 'Companies: Awaiting Approval (Company Scoped)', 'Companies created by client onboarding that are still awaiting approval, with the onboarding submission time. Company scoped: limited to the company the report is run for.', 'Companies and Onboarding', 'SELECT c.name AS company, c.phone, co.contact_name, co.recipient_email, co.submitted_at, co.status AS onboarding_status FROM companies c LEFT JOIN client_onboardings co ON co.company_id = c.id WHERE c.id = {{current.company}} AND c.pending_approval = 1 ORDER BY co.submitted_at ASC', 1),
('companies-user-and-asset-footprint-company-scoped', 'Companies: User and Asset Footprint (Company Scoped)', 'Per-company counts of active users and registered assets for capacity and onboarding planning. Company scoped: limited to the company the report is run for.', 'Companies and Onboarding', 'SELECT c.id AS company_id, c.name AS company, COALESCE(u_counts.active_user_count, 0) AS active_user_count, COALESCE(a_counts.asset_count, 0) AS asset_count FROM companies c LEFT JOIN (SELECT u.company_id, COUNT(*) AS active_user_count FROM users u WHERE u.is_active = 1 GROUP BY u.company_id) AS u_counts ON u_counts.company_id = c.id LEFT JOIN (SELECT a.company_id, COUNT(*) AS asset_count FROM assets a GROUP BY a.company_id) AS a_counts ON a_counts.company_id = c.id WHERE c.id = {{current.company}} ORDER BY c.name ASC', 1),
('dashboard-global-companies-company-scoped', 'Dashboard - Global companies (Company Scoped)', 'Dashboard panel: Global companies. Company scoped: limited to the company the report is run for.', 'Companies and Onboarding', 'SELECT id, name FROM companies WHERE id = {{current.company}}', 1),
('compliance-assignment-status-by-company-company-scoped', 'Compliance: Assignment Status by Company (Company Scoped)', 'Compliance assignment counts per company split by status (excluding archived assignments). Company scoped: limited to the company the report is run for.', 'Compliance', 'SELECT c.name AS company, SUM(CASE WHEN cca.status = ''compliant'' THEN 1 ELSE 0 END) AS compliant_count, SUM(CASE WHEN cca.status = ''non_compliant'' THEN 1 ELSE 0 END) AS non_compliant_count, SUM(CASE WHEN cca.status = ''in_progress'' THEN 1 ELSE 0 END) AS in_progress_count, SUM(CASE WHEN cca.status = ''not_started'' THEN 1 ELSE 0 END) AS not_started_count, COUNT(*) AS total_assignments FROM company_compliance_check_assignments cca JOIN companies c ON c.id = cca.company_id WHERE cca.company_id = {{current.company}} AND cca.archived = 0 GROUP BY c.id, c.name ORDER BY non_compliant_count DESC, in_progress_count DESC, company ASC', 1),
('smb1001-compliance-by-company-company-scoped', 'SMB1001: Compliance Status by Company (Company Scoped)', 'SMB1001 control status per company: compliant or not applicable, in progress, non-compliant and not started, with the completion percentage. Company scoped: limited to the company the report is run for.', 'Compliance', 'SELECT c.name AS company, COUNT(cc.id) AS controls_tracked, SUM(CASE WHEN cc.status IN (''compliant'', ''not_applicable'') THEN 1 ELSE 0 END) AS complete, SUM(CASE WHEN cc.status = ''in_progress'' THEN 1 ELSE 0 END) AS in_progress, SUM(CASE WHEN cc.status = ''non_compliant'' THEN 1 ELSE 0 END) AS non_compliant, (SELECT COUNT(*) FROM smb1001_controls) - SUM(CASE WHEN cc.status IN (''compliant'', ''not_applicable'', ''in_progress'', ''non_compliant'') THEN 1 ELSE 0 END) AS not_started, ROUND(100 * SUM(CASE WHEN cc.status IN (''compliant'', ''not_applicable'') THEN 1 ELSE 0 END) / NULLIF((SELECT COUNT(*) FROM smb1001_controls), 0), 1) AS complete_percent, MAX(cc.updated_at) AS last_updated_at FROM company_smb1001_compliance cc JOIN companies c ON c.id = cc.company_id WHERE cc.company_id = {{current.company}} GROUP BY cc.company_id, c.name ORDER BY complete_percent DESC', 1),
('smb1001-evidence-by-company-company-scoped', 'SMB1001: Evidence Uploaded by Company (Company Scoped)', 'Current SMB1001 evidence files per company with the number of controls evidenced and the last upload. Company scoped: limited to the company the report is run for.', 'Compliance', 'SELECT c.name AS company, COUNT(*) AS evidence_files, COUNT(DISTINCT e.control_id) AS controls_with_evidence, ROUND(SUM(e.file_size_bytes) / 1048576, 1) AS total_mb, MAX(e.uploaded_at) AS last_uploaded_at FROM company_smb1001_evidence e JOIN companies c ON c.id = e.company_id WHERE e.company_id = {{current.company}} AND e.is_current = 1 GROUP BY e.company_id, c.name ORDER BY controls_with_evidence DESC', 1),
('custom-form-submissions-recent-company-scoped', 'Custom Forms: Recent Submissions (Company Scoped)', 'Custom form submissions in the last 30 days with the form, submitter and resulting ticket. Company scoped: limited to the company the report is run for.', 'Forms and Feedback', 'SELECT s.created_at, f.name AS form, us.email AS submitted_by, t.ticket_number, t.status AS ticket_status, c.name AS company FROM custom_form_submissions s JOIN custom_forms f ON f.id = s.form_id LEFT JOIN users us ON us.id = s.submitted_by LEFT JOIN tickets t ON t.id = s.ticket_id LEFT JOIN companies c ON c.id = t.company_id WHERE COALESCE(t.company_id, us.company_id) = {{current.company}} AND s.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY s.created_at DESC', 1),
('user-feedback-negative-recent-company-scoped', 'Feedback: Recent Negative Feedback (Company Scoped)', 'Thumbs-down feedback from the last 30 days with the reason, suggested improvement, page and linked ticket. Company scoped: limited to the company the report is run for.', 'Forms and Feedback', 'SELECT f.created_at, us.email AS user_email, f.page_url, f.reason, f.suggested_improvements, t.ticket_number FROM user_feedback f LEFT JOIN users us ON us.id = f.user_id LEFT JOIN tickets t ON t.id = f.ticket_id WHERE us.company_id = {{current.company}} AND f.rating = ''down'' AND f.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY f.created_at DESC', 1),
('user-feedback-summary-company-scoped', 'Feedback: Ratings by Page (Last 90 Days) (Company Scoped)', 'Thumbs up and down feedback in the last 90 days grouped by page, with the satisfaction percentage. Company scoped: limited to the company the report is run for.', 'Forms and Feedback', 'SELECT COALESCE(SUBSTRING_INDEX(f.page_url, ''?'', 1), ''unknown'') AS page, COUNT(*) AS responses, SUM(CASE WHEN f.rating = ''up'' THEN 1 ELSE 0 END) AS thumbs_up, SUM(CASE WHEN f.rating = ''down'' THEN 1 ELSE 0 END) AS thumbs_down, ROUND(100 * SUM(CASE WHEN f.rating = ''up'' THEN 1 ELSE 0 END) / COUNT(*), 0) AS satisfaction_percent, MAX(f.created_at) AS last_feedback_at FROM user_feedback f JOIN users us ON us.id = f.user_id WHERE us.company_id = {{current.company}} AND f.created_at >= UTC_TIMESTAMP() - INTERVAL 90 DAY GROUP BY page ORDER BY thumbs_down DESC, responses DESC', 1),
('health-check-detection-tickets-company-scoped', 'Health Checks: Tickets by Detection (Company Scoped)', 'Tickets raised by health check detections grouped by detection, with open and total ticket counts and devices affected. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT d.detection_key, COUNT(*) AS tickets, SUM(CASE WHEN t.status NOT IN (''resolved'', ''closed'') THEN 1 ELSE 0 END) AS open_tickets, COUNT(DISTINCT d.asset_id) AS devices, COUNT(DISTINCT t.company_id) AS companies, MAX(d.updated_at) AS last_raised_at FROM ai_health_check_detection_tickets d JOIN tickets t ON t.id = d.ticket_id WHERE t.company_id = {{current.company}} GROUP BY d.detection_key ORDER BY open_tickets DESC, tickets DESC', 1),
('health-check-groups-company-scoped', 'Health Checks: Device Rule Groups (Company Scoped)', 'Health check device-rule groups with scope, whether they are enabled or the default, and when they last changed. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT g.name, COALESCE(c.name, ''All companies'') AS company, CASE WHEN g.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, CASE WHEN g.is_default = 1 THEN ''yes'' ELSE ''no'' END AS is_default, g.target_rules_json AS target_rules, g.updated_at FROM ai_health_check_groups g LEFT JOIN companies c ON c.id = g.company_id WHERE COALESCE(g.company_id, {{current.company}}) = {{current.company}} ORDER BY company, g.name', 1),
('health-check-remediations-company-scoped', 'Health Checks: Remediation Activity (Company Scoped)', 'Automatic remediations configured for health check detections with scope, script, ticket option, run count and last result. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT r.detection_key, COALESCE(c.name, ''All companies'') AS company, s.name AS script, CASE WHEN r.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, CASE WHEN r.create_ticket = 1 THEN ''yes'' ELSE ''no'' END AS creates_ticket, r.run_count, r.last_run_at, r.last_summary FROM ai_health_check_remediations r LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN rmm_scripts s ON s.id = r.script_id WHERE COALESCE(r.company_id, {{current.company}}) = {{current.company}} ORDER BY r.run_count DESC, r.detection_key', 1),
('health-check-schedules-company-scoped', 'Health Checks: Monthly Schedule Status (Company Scoped)', 'Scheduled monthly health checks per device with the next window, last start and result, flagging windows that ended without a run. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT c.name AS company, a.name AS device, s.next_run_at, s.window_ends_at, s.last_started_at, s.last_result, CASE WHEN s.window_ends_at < UTC_TIMESTAMP() AND (s.last_started_at IS NULL OR s.last_started_at < s.next_run_at) THEN ''missed'' ELSE ''ok'' END AS window_state FROM ai_health_check_schedules s LEFT JOIN companies c ON c.id = s.company_id LEFT JOIN assets a ON a.id = s.asset_id WHERE s.company_id = {{current.company}} ORDER BY window_state, s.next_run_at', 1),
('health-checks-failed-runs-company-scoped', 'Health Checks: Failed Runs (Last 30 Days) (Company Scoped)', 'Health check runs that failed in the last 30 days with the device, last stage reached and error. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT c.name AS company, a.name AS device, h.platform, h.run_source, h.stage_message, h.error, h.created_at FROM ai_health_checks h LEFT JOIN companies c ON c.id = h.company_id LEFT JOIN assets a ON a.id = h.asset_id WHERE h.company_id = {{current.company}} AND h.status = ''failed'' AND h.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY h.created_at DESC', 1),
('health-checks-latest-by-asset-company-scoped', 'Health Checks: Latest Result per Device (Company Scoped)', 'The most recent completed AI health check for each device with overall status, health score, platform and summary, worst first. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT c.name AS company, a.name AS device, h.overall_status, h.health_score, h.platform, h.run_source, h.completed_at, h.summary FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id LEFT JOIN companies c ON c.id = h.company_id LEFT JOIN assets a ON a.id = h.asset_id WHERE h.company_id = {{current.company}} ORDER BY FIELD(h.overall_status, ''critical'', ''attention'', ''healthy''), h.health_score ASC', 1),
('health-checks-monthly-trend-company-scoped', 'Health Checks: Monthly Score Trend (Company Scoped)', 'Completed health checks per month over the last 12 months with average score and the share of healthy, attention and critical results. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT DATE_FORMAT(h.completed_at, ''%Y-%m'') AS month, COUNT(*) AS checks, COUNT(DISTINCT h.asset_id) AS devices, ROUND(AVG(h.health_score), 1) AS avg_health_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical FROM ai_health_checks h WHERE h.company_id = {{current.company}} AND h.status = ''completed'' AND h.completed_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month ORDER BY month', 1),
('health-checks-run-outcomes-30-days-company-scoped', 'Health Checks: Run Outcomes (Last 30 Days) (Company Scoped)', 'Health check runs in the last 30 days by source (manual, schedule, ticket) and status, with average time to complete. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT h.run_source, h.status, COUNT(*) AS runs, COUNT(DISTINCT h.asset_id) AS devices, ROUND(AVG(CASE WHEN h.completed_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, h.created_at, h.completed_at) END), 0) AS avg_seconds_to_complete, MAX(h.created_at) AS last_run_at FROM ai_health_checks h WHERE h.company_id = {{current.company}} AND h.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY h.run_source, h.status ORDER BY h.run_source, runs DESC', 1),
('health-checks-score-by-company-company-scoped', 'Health Checks: Device Health by Company (Company Scoped)', 'Per company, the latest completed health check per device summarised as average score and healthy, attention and critical device counts. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT c.name AS company, COUNT(*) AS devices, ROUND(AVG(h.health_score), 0) AS avg_health_score, MIN(h.health_score) AS lowest_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical, MAX(h.completed_at) AS last_check_at FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id LEFT JOIN companies c ON c.id = h.company_id WHERE h.company_id = {{current.company}} GROUP BY h.company_id, c.name ORDER BY avg_health_score ASC', 1),
('stat-strip-health-checks-company-scoped', 'Stat Strip - Health Checks - Overview (Company Scoped)', 'Devices with a completed health check, average score, healthy, attention and critical devices, and health checks run in the last 30 days. Company scoped: limited to the company the report is run for.', 'Health Checks', 'SELECT COUNT(*) AS devices_checked, ROUND(AVG(h.health_score), 0) AS average_score, SUM(CASE WHEN h.overall_status = ''healthy'' THEN 1 ELSE 0 END) AS healthy, SUM(CASE WHEN h.overall_status = ''attention'' THEN 1 ELSE 0 END) AS attention, SUM(CASE WHEN h.overall_status = ''critical'' THEN 1 ELSE 0 END) AS critical, (SELECT COUNT(*) FROM ai_health_checks x WHERE x.company_id = {{current.company}} AND x.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS checks_last_30_days FROM ai_health_checks h JOIN (SELECT asset_id, MAX(id) AS id FROM ai_health_checks WHERE status = ''completed'' GROUP BY asset_id) latest ON latest.id = h.id WHERE h.company_id = {{current.company}}', 1),
('applications-importance-by-company-company-scoped', 'Applications: Importance Summary by Company (Company Scoped)', 'Count of documented applications per company by importance, and how many have no champion or no linked documentation. Company scoped: limited to the company the report is run for.', 'Knowledge and Documentation', 'SELECT c.name AS company, COUNT(*) AS applications, SUM(CASE WHEN ap.importance = ''critical'' THEN 1 ELSE 0 END) AS critical, SUM(CASE WHEN ap.importance = ''high'' THEN 1 ELSE 0 END) AS high, SUM(CASE WHEN ap.importance = ''medium'' THEN 1 ELSE 0 END) AS medium, SUM(CASE WHEN ap.importance = ''low'' THEN 1 ELSE 0 END) AS low, SUM(CASE WHEN ap.champion_staff_id IS NULL AND COALESCE(ap.champion_name, '''') = '''' THEN 1 ELSE 0 END) AS without_champion, SUM(CASE WHEN NOT EXISTS (SELECT 1 FROM application_kb_links k WHERE k.application_id = ap.id) THEN 1 ELSE 0 END) AS without_kb_article FROM applications ap LEFT JOIN companies c ON c.id = ap.company_id WHERE ap.company_id = {{current.company}} GROUP BY ap.company_id, c.name ORDER BY applications DESC', 1),
('applications-register-company-scoped', 'Applications: Register by Company (Company Scoped)', 'Documented line-of-business applications per company with type, version, importance, champion and linked knowledge base articles. Company scoped: limited to the company the report is run for.', 'Knowledge and Documentation', 'SELECT c.name AS company, ap.name AS application, ty.name AS application_type, ap.version, ap.importance, COALESCE(TRIM(CONCAT(COALESCE(st.first_name, ''''), '' '', COALESCE(st.last_name, ''''))), ap.champion_name) AS champion, (SELECT COUNT(*) FROM application_kb_links k WHERE k.application_id = ap.id) AS kb_articles, (SELECT COUNT(*) FROM application_external_links x WHERE x.application_id = ap.id) AS external_links, ap.updated_at FROM applications ap LEFT JOIN companies c ON c.id = ap.company_id LEFT JOIN application_types ty ON ty.id = ap.type_id LEFT JOIN staff st ON st.id = ap.champion_staff_id WHERE ap.company_id = {{current.company}} ORDER BY company, FIELD(ap.importance, ''critical'', ''high'', ''medium'', ''low''), application', 1),
('kb-recurring-issue-reviews-company-scoped', 'Knowledge Base: Recurring Issue Reviews (Company Scoped)', 'Recurring-issue clusters reviewed for knowledge base articles: whether an article was written or the cluster ignored, and who reviewed it. Company scoped: limited to the company the report is run for.', 'Knowledge and Documentation', 'SELECT r.anchor_ticket_id, t.subject AS anchor_subject, CASE WHEN r.ignored = 1 THEN ''ignored'' WHEN r.article_id IS NOT NULL THEN ''article written'' ELSE ''reviewed'' END AS outcome, kb.title AS article, us.email AS reviewed_by, r.updated_at FROM knowledge_base_recurring_issue_reviews r LEFT JOIN tickets t ON t.id = r.anchor_ticket_id LEFT JOIN knowledge_base_articles kb ON kb.id = r.article_id LEFT JOIN users us ON us.id = r.updated_by WHERE t.company_id = {{current.company}} ORDER BY r.updated_at DESC', 1),
('dashboard-global-available-licenses-company-scoped', 'Dashboard - Available licenses (Company Scoped)', 'Available Microsoft 365 license seats by company and product. Products hidden in the MyPortal license SKU mappings are excluded. Company scoped: limited to the company the report is run for.', 'Licenses and Subscriptions', 'SELECT license_totals.company_id, license_totals.company, license_totals.product, license_totals.total_licenses, license_totals.allocated_licenses, GREATEST(license_totals.total_licenses - license_totals.allocated_licenses, 0) AS available_licenses FROM (SELECT c.id AS company_id, c.name AS company, COALESCE(NULLIF(TRIM(lsn.friendly_name), ''''), l.name) AS product, l.count AS total_licenses, (SELECT COUNT(DISTINCT s.id) FROM staff s WHERE s.id IN (SELECT sl.staff_id FROM staff_licenses sl WHERE sl.license_id = l.id UNION SELECT ogm.staff_id FROM group_licenses gl INNER JOIN office_group_members ogm ON ogm.group_id = gl.group_id WHERE gl.license_id = l.id)) AS allocated_licenses FROM licenses l INNER JOIN companies c ON c.id = l.company_id LEFT JOIN license_sku_friendly_names lsn ON lsn.sku = l.platform WHERE COALESCE(lsn.hidden, 0) = 0) license_totals WHERE license_totals.company_id = {{current.company}} ORDER BY license_totals.company ASC, license_totals.product ASC', 1),
('licenses-expiring-next-90-days-company-scoped', 'Licenses: Expiring in Next 90 Days (Company Scoped)', 'Licenses with upcoming expiry dates in the next 90 days, including company and seat counts. Company scoped: limited to the company the report is run for.', 'Licenses and Subscriptions', 'SELECT COALESCE(c.name, ''(no company)'') AS company, l.name AS license_name, l.platform, l.count AS seat_count, l.expiry_date FROM licenses l LEFT JOIN companies c ON c.id = l.company_id WHERE l.company_id = {{current.company}} AND l.expiry_date IS NOT NULL AND l.expiry_date >= CURRENT_DATE AND l.expiry_date < (CURRENT_DATE + INTERVAL 90 DAY) ORDER BY l.expiry_date ASC, company ASC, l.name ASC', 1),
('subscriptions-status-by-company-company-scoped', 'Subscriptions: Status by Company (Company Scoped)', 'Subscription counts by company and status, with upcoming expiries in the next 30 days. Company scoped: limited to the company the report is run for.', 'Licenses and Subscriptions', 'SELECT c.name AS company, s.status, COUNT(*) AS subscription_count, SUM(CASE WHEN s.end_date >= CURRENT_DATE AND s.end_date < (CURRENT_DATE + INTERVAL 30 DAY) THEN 1 ELSE 0 END) AS expiring_next_30_days FROM subscriptions s JOIN companies c ON c.id = s.customer_id WHERE s.customer_id = {{current.company}} GROUP BY c.id, c.name, s.status ORDER BY company ASC, subscription_count DESC, s.status ASC', 1),
('marketing-bounces-and-skips-company-scoped', 'Marketing: Bounced and Skipped Recipients (Company Scoped)', 'Campaign recipients that bounced, failed or were skipped, with the skip reason or error, to clean up contact data. Company scoped: limited to the company the report is run for.', 'Marketing', 'SELECT mc.name AS campaign, COALESCE(c.name, ''No company'') AS company, r.email, r.name, r.status, r.skip_reason, r.error_message, r.bounced_at, r.updated_at FROM marketing_campaign_recipients r JOIN marketing_campaigns mc ON mc.id = r.campaign_id LEFT JOIN companies c ON c.id = r.company_id WHERE r.company_id = {{current.company}} AND (r.bounced_at IS NOT NULL OR r.status IN (''skipped'', ''failed'')) ORDER BY r.updated_at DESC', 1),
('marketing-campaign-engagement-by-company-company-scoped', 'Marketing: Campaign Engagement by Company (Company Scoped)', 'Marketing email engagement per recipient company across all campaigns: emails sent, opened, clicked, replied and bounced. Company scoped: limited to the company the report is run for.', 'Marketing', 'SELECT COALESCE(c.name, ''No company'') AS company, COUNT(*) AS emails, SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END) AS sent, SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened, SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) AS clicked, SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) AS replied, SUM(CASE WHEN r.bounced_at IS NOT NULL THEN 1 ELSE 0 END) AS bounced, COUNT(DISTINCT r.campaign_id) AS campaigns FROM marketing_campaign_recipients r LEFT JOIN companies c ON c.id = r.company_id WHERE r.company_id = {{current.company}} GROUP BY r.company_id, c.name ORDER BY opened DESC, emails DESC', 1),
('marketing-campaign-performance-company-scoped', 'Marketing: Campaign Performance (Company Scoped)', 'Marketing campaigns with recipients, sent, delivered, opened, clicked, bounced, skipped and replied counts, plus open, click and reply rates. Company scoped: limited to the company the report is run for.', 'Marketing', 'SELECT mc.name, mc.category, mc.status, mc.scheduled_for, mc.completed_at, COUNT(r.id) AS recipients, SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END) AS sent, SUM(CASE WHEN r.delivered_at IS NOT NULL THEN 1 ELSE 0 END) AS delivered, SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened, SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) AS clicked, SUM(CASE WHEN r.bounced_at IS NOT NULL THEN 1 ELSE 0 END) AS bounced, SUM(CASE WHEN r.status = ''skipped'' THEN 1 ELSE 0 END) AS skipped, SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) AS replied, ROUND(100 * SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END), 0), 1) AS open_rate_percent, ROUND(100 * SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END), 0), 1) AS click_rate_percent, ROUND(100 * SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END), 0), 1) AS reply_rate_percent FROM marketing_campaigns mc JOIN marketing_campaign_recipients r ON r.campaign_id = mc.id AND r.company_id = {{current.company}} GROUP BY mc.id, mc.name, mc.category, mc.status, mc.scheduled_for, mc.completed_at ORDER BY COALESCE(mc.completed_at, mc.scheduled_for, mc.created_at) DESC', 1),
('stat-strip-marketing-campaigns-company-scoped', 'Stat Strip - Marketing - Campaigns (Company Scoped)', 'Campaigns sent, emails sent, opened, clicked, replied and bounced across all marketing campaigns, and opt-outs in the last 30 days. Company scoped: limited to the company the report is run for.', 'Marketing', 'SELECT (SELECT COUNT(DISTINCT mc.id) FROM marketing_campaigns mc JOIN marketing_campaign_recipients mr ON mr.campaign_id = mc.id WHERE mc.status = ''completed'' AND mr.company_id = {{current.company}}) AS campaigns_completed, SUM(CASE WHEN r.sent_at IS NOT NULL THEN 1 ELSE 0 END) AS sent, SUM(CASE WHEN r.first_opened_at IS NOT NULL THEN 1 ELSE 0 END) AS opened, SUM(CASE WHEN r.first_clicked_at IS NOT NULL THEN 1 ELSE 0 END) AS clicked, SUM(CASE WHEN r.replied_at IS NOT NULL THEN 1 ELSE 0 END) AS replied, SUM(CASE WHEN r.bounced_at IS NOT NULL THEN 1 ELSE 0 END) AS bounced, (SELECT COUNT(*) FROM marketing_email_opt_outs o WHERE EXISTS (SELECT 1 FROM marketing_campaign_recipients orr WHERE orr.email = o.email AND orr.company_id = {{current.company}}) AND o.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS opt_outs_30_days FROM marketing_campaign_recipients r WHERE r.company_id = {{current.company}}', 1),
('office365-best-practice-status-by-company-company-scoped', 'Office 365: Best Practice Status by Company (Company Scoped)', 'Current Microsoft 365 best-practice status counts per company. Company scoped: limited to the company the report is run for.', 'Microsoft 365', 'SELECT c.name AS company, SUM(CASE WHEN r.status = ''pass'' THEN 1 ELSE 0 END) AS pass_checks, SUM(CASE WHEN r.status = ''fail'' THEN 1 ELSE 0 END) AS fail_checks, SUM(CASE WHEN r.status = ''unknown'' THEN 1 ELSE 0 END) AS unknown_checks, SUM(CASE WHEN r.status = ''not_applicable'' THEN 1 ELSE 0 END) AS not_applicable_checks, MAX(r.run_at) AS last_run_at FROM m365_best_practice_results r JOIN companies c ON c.id = r.company_id WHERE r.company_id = {{current.company}} GROUP BY c.id, c.name ORDER BY fail_checks DESC, unknown_checks DESC, company ASC', 1),
('global-subnet-scanners-company-scoped', 'Subnet Scanners - All Companies (Company Scoped)', 'All enabled subnet scanners across every company, including the nominated device and each subnet it has scanned. Company scoped: limited to the company the report is run for.', 'Network and Discovery', 'SELECT c.name AS company, COALESCE(NULLIF(a.name, ''''), NULLIF(td.hostname, ''''), CONCAT(''Tray device #'', td.id)) AS scanner_device, COALESCE(nss.subnet, ''No subnet recorded'') AS scanned_subnet FROM tray_devices td INNER JOIN companies c ON c.id = td.company_id LEFT JOIN assets a ON a.id = td.asset_id LEFT JOIN network_scan_subnets nss ON nss.scanner_tray_device_id = td.id AND nss.company_id = td.company_id WHERE td.company_id = {{current.company}} AND td.network_scanner_enabled = 1 ORDER BY c.name ASC, scanner_device ASC, nss.subnet ASC', 1),
('network-map-documentation-coverage-company-scoped', 'Network Map: Documentation Coverage by Company (Company Scoped)', 'Per company, documented network interfaces and links by medium (copper, fibre, wireless and other), to show which sites have a mapped network. Company scoped: limited to the company the report is run for.', 'Network and Discovery', 'SELECT c.name AS company, (SELECT COUNT(*) FROM asset_interfaces i WHERE i.company_id = c.id) AS interfaces, (SELECT COUNT(DISTINCT i.asset_id) FROM asset_interfaces i WHERE i.company_id = c.id) AS assets_with_interfaces, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id) AS links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium = ''copper'') AS copper_links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium = ''fibre'') AS fibre_links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium IN (''wireless'', ''radio'')) AS wireless_links, (SELECT COUNT(*) FROM network_links l WHERE l.company_id = c.id AND l.medium NOT IN (''copper'', ''fibre'', ''wireless'', ''radio'')) AS other_links FROM companies c WHERE c.id = {{current.company}} AND c.archived = 0 ORDER BY links DESC, company', 1),
('rmm-patch-policies-company-scoped', 'RMM: Patch Policies (Company Scoped)', 'Windows Update and Chocolatey patch policies with scope, schedule, next run and last change. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT p.name, COALESCE(c.name, ''All companies'') AS company, p.kind, NULLIF(p.package_id, '''') AS package_id, p.cron, p.timezone, CASE WHEN p.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, p.next_run_at, p.revision, p.updated_at FROM rmm_patch_policies p LEFT JOIN companies c ON c.id = p.company_id WHERE COALESCE(p.company_id, {{current.company}}) = {{current.company}} ORDER BY company, p.name', 1),
('rmm-windows-update-blocks-company-scoped', 'Windows Updates: Blocked Updates Register (Company Scoped)', 'Windows updates blocked from installation, with scope (all companies, a company or a single asset), reason and who blocked them. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT COALESCE(c.name, ''All companies'') AS company, a.name AS asset, b.kb, b.update_id, b.title, b.reason, TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS blocked_by, b.created_at FROM rmm_windows_update_blocks b LEFT JOIN companies c ON c.id = b.company_id LEFT JOIN assets a ON a.id = b.asset_id LEFT JOIN users us ON us.id = b.created_by_user_id WHERE COALESCE(b.company_id, {{current.company}}) = {{current.company}} ORDER BY b.created_at DESC', 1),
('rmm-windows-updates-failed-installs-30-days-company-scoped', 'Windows Updates: Failed Installs (Last 30 Days) (Company Scoped)', 'Windows update installs that failed in the last 30 days, with the HRESULT error code and the application that ran the install. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, h.kb, h.title, h.classification, h.hresult, h.client_application, h.source, h.occurred_at FROM rmm_windows_update_history h JOIN rmm_agents ag ON ag.id = h.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.company_id = {{current.company}} AND h.operation = ''install'' AND h.result = ''failed'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY h.occurred_at DESC', 1),
('rmm-windows-updates-failure-codes-company-scoped', 'Windows Updates: Install Failures by Error Code (Last 90 Days) (Company Scoped)', 'Failed Windows update installs in the last 90 days grouped by HRESULT so recurring causes stand out. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT COALESCE(h.hresult, ''none'') AS hresult, COUNT(*) AS failures, COUNT(DISTINCT h.agent_id) AS devices, COUNT(DISTINCT h.kb) AS distinct_kbs, MAX(h.occurred_at) AS last_failure_at FROM rmm_windows_update_history h JOIN rmm_agents ag ON ag.id = h.agent_id WHERE ag.company_id = {{current.company}} AND h.operation = ''install'' AND h.result = ''failed'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 90 DAY GROUP BY h.hresult ORDER BY failures DESC', 1),
('rmm-windows-updates-install-history-monthly-company-scoped', 'Windows Updates: Install Results by Month (Company Scoped)', 'Windows update install operations per month over the last 12 months: succeeded, succeeded with errors, failed and cancelled. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT DATE_FORMAT(h.occurred_at, ''%Y-%m'') AS month, COUNT(*) AS installs, SUM(CASE WHEN h.result = ''succeeded'' THEN 1 ELSE 0 END) AS succeeded, SUM(CASE WHEN h.result = ''succeeded_with_errors'' THEN 1 ELSE 0 END) AS succeeded_with_errors, SUM(CASE WHEN h.result = ''failed'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN h.result = ''aborted'' THEN 1 ELSE 0 END) AS cancelled, COUNT(DISTINCT h.agent_id) AS devices FROM rmm_windows_update_history h JOIN rmm_agents ag ON ag.id = h.agent_id WHERE ag.company_id = {{current.company}} AND h.operation = ''install'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month ORDER BY month', 1),
('rmm-windows-updates-missing-by-classification-company-scoped', 'Windows Updates: Missing Updates by Company and Classification (Company Scoped)', 'Missing (not hidden) Windows updates per company split by classification, counting update instances and affected devices. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT c.name AS company, COALESCE(u.classification, ''Unclassified'') AS classification, COUNT(*) AS missing_updates, COUNT(DISTINCT u.agent_id) AS devices FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND u.is_hidden = 0 GROUP BY ag.company_id, c.name, u.classification ORDER BY company, missing_updates DESC', 1),
('rmm-windows-updates-missing-by-device-company-scoped', 'Windows Updates: Missing Updates by Device (Company Scoped)', 'Latest Windows Update scan per device with missing, security and critical update counts, pending reboot and scan age. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, sc.missing_count, (SELECT COUNT(*) FROM rmm_windows_updates u WHERE u.agent_id = sc.agent_id AND u.is_hidden = 0 AND u.classification LIKE ''%Security%'') AS security_missing, (SELECT COUNT(*) FROM rmm_windows_updates u WHERE u.agent_id = sc.agent_id AND u.is_hidden = 0 AND u.severity = ''Critical'') AS critical_missing, CASE WHEN sc.reboot_pending = 1 THEN ''yes'' ELSE ''no'' END AS reboot_pending, sc.update_source, sc.scanned_at, TIMESTAMPDIFF(DAY, sc.scanned_at, UTC_TIMESTAMP()) AS scan_age_days FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id LEFT JOIN companies c ON c.id = sc.company_id LEFT JOIN assets a ON a.id = sc.asset_id WHERE sc.company_id = {{current.company}} AND ag.status = ''active'' ORDER BY sc.missing_count DESC, company, device', 1),
('rmm-windows-updates-most-missing-company-scoped', 'Windows Updates: Most Commonly Missing Updates (Company Scoped)', 'Missing (not hidden) Windows updates ranked by the number of devices that need them, with KB, classification and severity. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT u.kb, u.title, u.classification, u.severity, u.released_on, COUNT(DISTINCT u.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies, ROUND(MAX(u.size_bytes) / 1048576, 1) AS size_mb, MIN(u.first_seen_at) AS first_seen_at FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND u.is_hidden = 0 GROUP BY u.update_id, u.kb, u.title, u.classification, u.severity, u.released_on ORDER BY devices DESC, u.released_on', 1),
('rmm-windows-updates-reboot-pending-company-scoped', 'Windows Updates: Devices Awaiting a Reboot (Company Scoped)', 'Active devices whose latest Windows Update scan reports a pending reboot, with last boot and check-in times. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, sc.scanned_at, inv.last_boot_at, ag.last_seen_utc, sc.missing_count FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id LEFT JOIN rmm_device_inventory inv ON inv.agent_id = sc.agent_id LEFT JOIN companies c ON c.id = sc.company_id LEFT JOIN assets a ON a.id = sc.asset_id WHERE sc.company_id = {{current.company}} AND ag.status = ''active'' AND sc.reboot_pending = 1 ORDER BY inv.last_boot_at ASC', 1),
('rmm-windows-updates-scan-stale-company-scoped', 'Windows Updates: Devices Not Scanned in 7 Days (Company Scoped)', 'Active Windows RMM agents with no Windows Update scan, or whose last scan is more than 7 days old. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ag.os_version, ag.last_seen_utc, sc.scanned_at, sc.scan_requested_at, sc.errors_json AS scan_errors FROM rmm_agents ag LEFT JOIN rmm_windows_update_scans sc ON sc.agent_id = ag.id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND ag.os = ''windows'' AND (sc.scanned_at IS NULL OR sc.scanned_at < UTC_TIMESTAMP() - INTERVAL 7 DAY) ORDER BY sc.scanned_at IS NULL DESC, sc.scanned_at ASC', 1),
('stat-strip-windows-updates-company-scoped', 'Stat Strip - Windows Updates - Overview (Company Scoped)', 'Devices scanned, devices with missing updates, missing security updates, devices awaiting a reboot and failed installs in the last 30 days. Company scoped: limited to the company the report is run for.', 'Patching and Windows Updates', 'SELECT (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'') AS devices_scanned, (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND sc.missing_count > 0) AS devices_missing_updates, (SELECT COUNT(*) FROM rmm_windows_updates u JOIN rmm_agents ag ON ag.id = u.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND u.is_hidden = 0 AND u.classification LIKE ''%Security%'') AS missing_security_updates, (SELECT COUNT(*) FROM rmm_windows_update_scans sc JOIN rmm_agents ag ON ag.id = sc.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND sc.reboot_pending = 1) AS reboot_pending, (SELECT COUNT(*) FROM rmm_windows_update_history h JOIN rmm_agents ag ON ag.id = h.agent_id WHERE ag.company_id = {{current.company}} AND h.operation = ''install'' AND h.result = ''failed'' AND h.occurred_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS failed_installs', 1),
('dashboard-global-rmm-agents-by-company-company-scoped', 'Dashboard - Global RMM agents by company (Company Scoped)', 'Active RMM agents per company (X) across the portal (Y). Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT COALESCE(c.name, ''Unassigned'') AS X, COUNT(*) AS Y FROM rmm_agents ag LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' GROUP BY X ORDER BY Y DESC', 1),
('rmm-agent-deployment-gaps-company-scoped', 'RMM: Tray Devices Without an RMM Agent (Company Scoped)', 'Active tray devices that have no active RMM agent yet, with the company''s automatic deployment setting and the latest install attempt. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, td.hostname, td.os, td.os_version, td.agent_version AS tray_version, td.last_seen_utc, CASE WHEN c.rmm_agent_auto_deploy = 1 THEN ''yes'' ELSE ''no'' END AS auto_deploy_enabled, (SELECT i.outcome FROM rmm_agent_install_attempts i WHERE i.tray_device_id = td.id ORDER BY i.created_at DESC, i.id DESC LIMIT 1) AS last_install_outcome, (SELECT i.message FROM rmm_agent_install_attempts i WHERE i.tray_device_id = td.id ORDER BY i.created_at DESC, i.id DESC LIMIT 1) AS last_install_message, (SELECT MAX(i.created_at) FROM rmm_agent_install_attempts i WHERE i.tray_device_id = td.id) AS last_install_attempt_at FROM tray_devices td LEFT JOIN companies c ON c.id = td.company_id WHERE td.company_id = {{current.company}} AND td.status = ''active'' AND NOT EXISTS (SELECT 1 FROM rmm_agents ag WHERE ag.tray_device_id = td.id AND ag.status = ''active'') ORDER BY company, td.hostname', 1),
('rmm-agent-install-attempts-last-30-days-company-scoped', 'RMM: Agent Install Attempts (Last 30 Days) (Company Scoped)', 'RMM agent deployment attempts in the last 30 days by company, source (auto, manual, repair) and outcome. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, i.source, i.outcome, COUNT(*) AS attempts, MAX(i.created_at) AS last_attempt_at FROM rmm_agent_install_attempts i LEFT JOIN companies c ON c.id = i.company_id WHERE i.company_id = {{current.company}} AND i.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY i.company_id, c.name, i.source, i.outcome ORDER BY company, attempts DESC', 1),
('rmm-agent-version-distribution-company-scoped', 'RMM: Agent Version Distribution (Company Scoped)', 'Active RMM agents grouped by platform and agent version, with how many support script files, run-as-user and run-anyway. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT ag.os AS platform, COALESCE(ag.agent_version, ''unknown'') AS agent_version, COUNT(*) AS agents, SUM(ag.script_files_supported) AS script_files_supported, SUM(ag.run_as_user_supported) AS run_as_user_supported, SUM(ag.run_anyway_supported) AS run_anyway_supported, MAX(ag.last_seen_utc) AS last_check_in_utc FROM rmm_agents ag WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' GROUP BY ag.os, ag.agent_version ORDER BY platform, agents DESC', 1),
('rmm-agents-by-company-company-scoped', 'RMM: Agent Coverage and Status by Company (Company Scoped)', 'Active RMM agents per company with online (seen in the last 15 minutes), offline, offline-over-7-days and per-platform counts. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, COUNT(*) AS agents, SUM(CASE WHEN ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN 1 ELSE 0 END) AS online, SUM(CASE WHEN ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 15 MINUTE THEN 1 ELSE 0 END) AS offline, SUM(CASE WHEN ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 7 DAY THEN 1 ELSE 0 END) AS offline_over_7_days, SUM(CASE WHEN ag.os = ''windows'' THEN 1 ELSE 0 END) AS windows, SUM(CASE WHEN ag.os = ''darwin'' THEN 1 ELSE 0 END) AS macos, SUM(CASE WHEN ag.os = ''linux'' THEN 1 ELSE 0 END) AS linux, MAX(ag.last_seen_utc) AS last_check_in_utc FROM rmm_agents ag LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' GROUP BY ag.company_id, c.name ORDER BY agents DESC, company', 1),
('rmm-agents-offline-over-7-days-company-scoped', 'RMM: Agents Offline for More Than 7 Days (Company Scoped)', 'Active RMM agents that have not checked in for over 7 days, oldest first, with the linked asset and days offline. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ag.hostname, ag.os, ag.os_version, ag.agent_version, ag.last_ip, ag.last_seen_utc, TIMESTAMPDIFF(DAY, ag.last_seen_utc, UTC_TIMESTAMP()) AS days_offline FROM rmm_agents ag LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND (ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 7 DAY) ORDER BY ag.last_seen_utc IS NULL DESC, ag.last_seen_utc ASC', 1),
('rmm-automation-open-tickets-company-scoped', 'RMM: Open Tickets Raised by Automation (Company Scoped)', 'Open tickets raised by RMM checks, event log rules, script result rules and health check detections, with the rule or detection that raised them. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT x.origin, x.rule_name, t.ticket_number, t.subject, c.name AS company, t.status, t.priority, t.created_at FROM ( SELECT ''RMM check'' AS origin, ch.name AS rule_name, st.ticket_id FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id WHERE st.ticket_id IS NOT NULL UNION ALL SELECT ''Event log rule'', r.name, rt.ticket_id FROM rmm_event_log_rule_tickets rt JOIN rmm_event_log_rules r ON r.id = rt.rule_id UNION ALL SELECT ''Script result rule'', r.name, rt.ticket_id FROM rmm_script_result_rule_tickets rt JOIN rmm_script_result_rules r ON r.id = rt.rule_id UNION ALL SELECT ''Health check detection'', d.detection_key, d.ticket_id FROM ai_health_check_detection_tickets d ) x JOIN tickets t ON t.id = x.ticket_id LEFT JOIN companies c ON c.id = t.company_id WHERE t.company_id = {{current.company}} AND t.status NOT IN (''resolved'', ''closed'') ORDER BY t.created_at DESC', 1),
('rmm-check-health-by-check-company-scoped', 'RMM Checks: Result Summary by Check (Company Scoped)', 'Every RMM check with passing, problem, failing and waiting device counts and the last time it failed. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT ch.name AS check_name, ch.check_type, ch.target, COALESCE(c.name, ''All companies'') AS company, ch.action, CASE WHEN ch.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, COUNT(st.agent_id) AS devices, SUM(CASE WHEN st.status = ''passing'' THEN 1 ELSE 0 END) AS passing, SUM(CASE WHEN st.status = ''warning'' THEN 1 ELSE 0 END) AS warning, SUM(CASE WHEN st.status = ''failing'' THEN 1 ELSE 0 END) AS failing, SUM(CASE WHEN st.status = ''pending'' THEN 1 ELSE 0 END) AS pending, ch.last_failed_at FROM rmm_checks ch LEFT JOIN rmm_check_states st ON st.check_id = ch.id AND st.agent_id IN (SELECT ag.id FROM rmm_agents ag WHERE ag.company_id = {{current.company}}) LEFT JOIN companies c ON c.id = ch.company_id WHERE COALESCE(ch.company_id, {{current.company}}) = {{current.company}} GROUP BY ch.id, ch.name, ch.check_type, ch.target, c.name, ch.action, ch.is_enabled, ch.last_failed_at ORDER BY failing DESC, warning DESC, ch.name', 1),
('rmm-checks-by-company-company-scoped', 'RMM Checks: Problems by Company (Company Scoped)', 'Check results per company for active agents: passing, warning and failing counts and devices with at least one problem. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, COUNT(*) AS results, SUM(CASE WHEN st.status = ''passing'' THEN 1 ELSE 0 END) AS passing, SUM(CASE WHEN st.status = ''warning'' THEN 1 ELSE 0 END) AS warning, SUM(CASE WHEN st.status = ''failing'' THEN 1 ELSE 0 END) AS failing, COUNT(DISTINCT CASE WHEN st.status IN (''warning'', ''failing'') THEN st.agent_id END) AS devices_with_problems FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id JOIN rmm_agents ag ON ag.id = st.agent_id LEFT JOIN companies c ON c.id = ag.company_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND ch.is_enabled = 1 GROUP BY ag.company_id, c.name ORDER BY failing DESC, warning DESC', 1),
('rmm-checks-failing-now-company-scoped', 'RMM Checks: Devices Currently Failing or Warning (Company Scoped)', 'Check results currently failing or warning, with the value seen, how long the problem has lasted and any linked ticket. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ch.name AS check_name, ch.check_type, ch.target, st.status, st.value_text, st.problem_since, TIMESTAMPDIFF(HOUR, st.problem_since, UTC_TIMESTAMP()) AS hours_in_problem, st.checked_at, t.ticket_number, t.status AS ticket_status FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id JOIN rmm_agents ag ON ag.id = st.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id LEFT JOIN tickets t ON t.id = st.ticket_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND ch.is_enabled = 1 AND st.status IN (''failing'', ''warning'') ORDER BY st.status, st.problem_since ASC', 1),
('rmm-event-log-rules-activity-company-scoped', 'RMM: Event Log Rule Activity (Company Scoped)', 'Event log rules with scope, action, match count, last match, devices triggered and open tickets they raised. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT r.name, COALESCE(c.name, ''All companies'') AS company, r.action, CASE WHEN r.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, r.match_count, r.last_matched_at, r.cooldown_minutes, (SELECT COUNT(*) FROM rmm_event_log_rule_triggers tr JOIN rmm_agents ag ON ag.id = tr.agent_id WHERE tr.rule_id = r.id AND ag.company_id = {{current.company}}) AS devices_triggered, (SELECT COUNT(*) FROM rmm_event_log_rule_tickets rt JOIN tickets t ON t.id = rt.ticket_id WHERE rt.rule_id = r.id AND t.company_id = {{current.company}} AND t.status NOT IN (''resolved'', ''closed'')) AS open_tickets, r.last_run_summary FROM rmm_event_log_rules r LEFT JOIN companies c ON c.id = r.company_id WHERE COALESCE(r.company_id, {{current.company}}) = {{current.company}} ORDER BY r.match_count DESC, r.name', 1),
('rmm-findings-by-category-company-scoped', 'RMM Findings: Summary by Category and Severity (Company Scoped)', 'Active RMM findings grouped by category and severity with open, acknowledged and dismissed counts. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT f.category, f.severity, COUNT(*) AS findings, SUM(CASE WHEN f.status = ''open'' THEN 1 ELSE 0 END) AS open, SUM(CASE WHEN f.status = ''acknowledged'' THEN 1 ELSE 0 END) AS acknowledged, SUM(CASE WHEN f.status = ''dismissed'' THEN 1 ELSE 0 END) AS dismissed, SUM(f.occurrences) AS occurrences, MAX(f.last_seen_at) AS last_seen_at FROM rmm_findings f WHERE JSON_CONTAINS(f.company_ids_json, CONCAT('''', {{current.company}})) AND f.is_active = 1 GROUP BY f.category, f.severity ORDER BY f.category, FIELD(f.severity, ''critical'', ''high'', ''medium'', ''low'', ''info'')', 1),
('rmm-findings-open-company-scoped', 'RMM Findings: Open Findings by Severity (Company Scoped)', 'Active RMM findings that are open or acknowledged, most severe first, with category, occurrences and first and last seen. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT f.severity, f.category, f.title, f.status, f.source, f.occurrences, f.confidence, f.first_seen_at, f.last_seen_at, f.recommendation FROM rmm_findings f WHERE JSON_CONTAINS(f.company_ids_json, CONCAT('''', {{current.company}})) AND f.is_active = 1 AND f.status IN (''open'', ''acknowledged'') ORDER BY FIELD(f.severity, ''critical'', ''high'', ''medium'', ''low'', ''info''), f.last_seen_at DESC', 1),
('rmm-onboarding-runs-30-days-company-scoped', 'RMM: Device Onboarding Runs (Last 30 Days) (Company Scoped)', 'Automatic device onboarding runs in the last 30 days per company: completed, failed and still running, with failed steps and average duration. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, COUNT(*) AS runs, SUM(CASE WHEN o.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN o.status = ''failed'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN o.status = ''running'' THEN 1 ELSE 0 END) AS running, SUM(o.failed_steps) AS failed_steps, ROUND(AVG(CASE WHEN o.completed_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, o.started_at, o.completed_at) END), 0) AS avg_minutes, MAX(o.started_at) AS last_started_at FROM rmm_onboarding_runs o LEFT JOIN companies c ON c.id = o.company_id WHERE o.company_id = {{current.company}} AND o.started_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY o.company_id, c.name ORDER BY runs DESC', 1),
('rmm-onboarding-steps-by-company-company-scoped', 'RMM: Onboarding Steps by Company (Company Scoped)', 'Configured device onboarding steps per company in order, with the script or package step, run-as account and failure handling. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT c.name AS company, st.position, COALESCE(s.name, ''Chocolatey packages'') AS step, st.package_ids_json AS packages, st.target_mode, st.run_as, st.timeout_seconds, CASE WHEN st.continue_on_failure = 1 THEN ''continue'' ELSE ''stop'' END AS on_failure, st.skip_existing_before FROM rmm_onboarding_steps st LEFT JOIN rmm_scripts s ON s.id = st.script_id LEFT JOIN companies c ON c.id = st.company_id WHERE st.company_id = {{current.company}} ORDER BY company, st.position', 1),
('rmm-remote-sessions-30-days-company-scoped', 'RMM: Remote Control Sessions (Last 30 Days) (Company Scoped)', 'Remote control sessions in the last 30 days per technician and provider, with how many became ready and the average time to connect. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS technician, rs.provider, rs.mode, COUNT(*) AS sessions, SUM(CASE WHEN rs.ready_at IS NOT NULL THEN 1 ELSE 0 END) AS connected, SUM(CASE WHEN rs.status = ''failed'' THEN 1 ELSE 0 END) AS failed, ROUND(AVG(CASE WHEN rs.ready_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, rs.created_at, rs.ready_at) END), 0) AS avg_seconds_to_ready, COUNT(DISTINCT rs.asset_id) AS devices, COUNT(DISTINCT rs.company_id) AS companies FROM rmm_remote_sessions rs LEFT JOIN users us ON us.id = rs.requested_by_user_id WHERE rs.company_id = {{current.company}} AND rs.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY rs.requested_by_user_id, us.first_name, us.last_name, rs.provider, rs.mode ORDER BY sessions DESC', 1),
('rmm-script-result-rules-activity-company-scoped', 'RMM: Script Result Rule Activity (Company Scoped)', 'Script result rules with the script they watch, the action taken, match count, last match and open tickets they raised. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT r.name, COALESCE(c.name, ''All companies'') AS company, COALESCE(s.name, ''Any script'') AS watched_script, r.action, ns.name AS next_script, CASE WHEN r.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, r.match_count, r.last_matched_at, (SELECT COUNT(*) FROM rmm_script_result_rule_tickets rt JOIN tickets t ON t.id = rt.ticket_id WHERE rt.rule_id = r.id AND t.company_id = {{current.company}} AND t.status NOT IN (''resolved'', ''closed'')) AS open_tickets, r.last_run_summary FROM rmm_script_result_rules r LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN rmm_scripts s ON s.id = r.script_id LEFT JOIN rmm_scripts ns ON ns.id = r.next_script_id WHERE COALESCE(r.company_id, {{current.company}}) = {{current.company}} ORDER BY r.match_count DESC, r.name', 1),
('stat-strip-rmm-overview-company-scoped', 'Stat Strip - RMM - Fleet Overview (Company Scoped)', 'Active RMM agents, online now, offline over 7 days, failing checks, script runs and failures today, and open findings. Company scoped: limited to the company the report is run for.', 'RMM', 'SELECT (SELECT COUNT(*) FROM rmm_agents ag WHERE ag.company_id = {{current.company}} AND ag.status = ''active'') AS agents, (SELECT COUNT(*) FROM rmm_agents ag WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 15 MINUTE) AS online, (SELECT COUNT(*) FROM rmm_agents ag WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND (ag.last_seen_utc IS NULL OR ag.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 7 DAY)) AS stale_agents, (SELECT COUNT(*) FROM rmm_check_states st JOIN rmm_checks ch ON ch.id = st.check_id JOIN rmm_agents ag ON ag.id = st.agent_id WHERE ag.company_id = {{current.company}} AND ch.is_enabled = 1 AND st.status = ''failing'') AS failing_checks, (SELECT COUNT(*) FROM rmm_script_runs r WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_DATE()) AS script_runs_today, (SELECT COUNT(*) FROM rmm_script_runs r WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_DATE() AND r.status IN (''failed'', ''timed_out'')) AS failed_runs_today, (SELECT COUNT(*) FROM rmm_findings f WHERE JSON_CONTAINS(f.company_ids_json, CONCAT('''', {{current.company}})) AND f.is_active = 1 AND f.status = ''open'') AS open_findings', 1),
('rmm-hardware-inventory-company-scoped', 'RMM Inventory: Hardware Summary (Company Scoped)', 'Latest RMM hardware inventory per device: manufacturer, model, serial, BIOS, CPU, memory, disk capacity, free system disk and last boot. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.manufacturer, inv.model, inv.serial_number, inv.bios_version, inv.os_name, inv.os_version, inv.os_build, inv.cpu_model, inv.cpu_cores, inv.cpu_logical_processors, ROUND(inv.ram_bytes / 1073741824, 1) AS ram_gb, ROUND(inv.disk_total_bytes / 1073741824, 0) AS disk_total_gb, ROUND(inv.system_disk_free_bytes / 1073741824, 1) AS system_disk_free_gb, inv.last_boot_at, inv.software_count, inv.collected_at FROM rmm_device_inventory inv LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE inv.company_id = {{current.company}} ORDER BY company, device', 1),
('rmm-inventory-long-uptime-company-scoped', 'RMM Inventory: Devices Not Restarted in 30 Days (Company Scoped)', 'Online RMM devices whose last boot was more than 30 days ago, longest uptime first. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.os_name, inv.last_boot_at, TIMESTAMPDIFF(DAY, inv.last_boot_at, UTC_TIMESTAMP()) AS uptime_days, ag.last_seen_utc FROM rmm_device_inventory inv JOIN rmm_agents ag ON ag.id = inv.agent_id LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE inv.company_id = {{current.company}} AND ag.status = ''active'' AND ag.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 2 DAY AND inv.last_boot_at < UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY inv.last_boot_at ASC', 1),
('rmm-inventory-low-memory-company-scoped', 'RMM Inventory: Devices With Less Than 8 GB RAM (Company Scoped)', 'Devices reporting under 8 GB of memory in RMM inventory, typically hardware refresh candidates. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.manufacturer, inv.model, inv.os_name, ROUND(inv.ram_bytes / 1073741824, 1) AS ram_gb, inv.cpu_model, inv.collected_at FROM rmm_device_inventory inv LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE inv.company_id = {{current.company}} AND inv.ram_bytes IS NOT NULL AND inv.ram_bytes < 8589934592 ORDER BY inv.ram_bytes ASC, company, device', 1),
('rmm-inventory-low-system-disk-company-scoped', 'RMM Inventory: Low System Disk Space (Company Scoped)', 'Devices whose system disk has less than 15% or less than 20 GB free, lowest free space first. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, inv.hostname) AS device, inv.os_name, ROUND(inv.system_disk_free_bytes / 1073741824, 1) AS system_disk_free_gb, ROUND(inv.disk_total_bytes / 1073741824, 0) AS disk_total_gb, ROUND(100 * inv.system_disk_free_bytes / NULLIF(inv.disk_total_bytes, 0), 1) AS free_percent_of_total_disk, inv.collected_at FROM rmm_device_inventory inv LEFT JOIN companies c ON c.id = inv.company_id LEFT JOIN assets a ON a.id = inv.asset_id WHERE inv.company_id = {{current.company}} AND inv.system_disk_free_bytes IS NOT NULL AND (inv.system_disk_free_bytes < 21474836480 OR inv.system_disk_free_bytes < 0.15 * NULLIF(inv.disk_total_bytes, 0)) ORDER BY inv.system_disk_free_bytes ASC', 1),
('rmm-inventory-manufacturer-model-company-scoped', 'RMM Inventory: Devices by Manufacturer and Model (Company Scoped)', 'Device counts by manufacturer and model from RMM inventory, with average memory and the oldest and newest BIOS seen. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT COALESCE(NULLIF(inv.manufacturer, ''''), ''Unknown'') AS manufacturer, COALESCE(NULLIF(inv.model, ''''), ''Unknown'') AS model, COUNT(*) AS devices, COUNT(DISTINCT inv.company_id) AS companies, ROUND(AVG(inv.ram_bytes) / 1073741824, 1) AS avg_ram_gb, MIN(inv.bios_version) AS min_bios_version, MAX(inv.bios_version) AS max_bios_version FROM rmm_device_inventory inv WHERE inv.company_id = {{current.company}} GROUP BY manufacturer, model ORDER BY devices DESC, manufacturer, model', 1),
('rmm-inventory-os-builds-company-scoped', 'RMM Inventory: Operating System Builds (Company Scoped)', 'Device counts by operating system name, version and build from RMM inventory, to spot out-of-date feature releases. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT COALESCE(inv.os_name, ''Unknown'') AS os_name, inv.os_version, inv.os_build, COUNT(*) AS devices, COUNT(DISTINCT inv.company_id) AS companies, MAX(inv.collected_at) AS latest_inventory FROM rmm_device_inventory inv WHERE inv.company_id = {{current.company}} GROUP BY inv.os_name, inv.os_version, inv.os_build ORDER BY os_name, inv.os_version, inv.os_build', 1),
('rmm-inventory-stale-company-scoped', 'RMM Inventory: Stale or Missing Inventory (Company Scoped)', 'Active RMM agents with no inventory or an inventory older than 7 days. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, ag.os, ag.last_seen_utc, inv.collected_at AS inventory_collected_at, inv.received_at AS inventory_received_at, inv.refresh_requested_at FROM rmm_agents ag LEFT JOIN rmm_device_inventory inv ON inv.agent_id = ag.id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND (inv.id IS NULL OR inv.received_at IS NULL OR inv.received_at < UTC_TIMESTAMP() - INTERVAL 7 DAY) ORDER BY inv.received_at IS NULL DESC, inv.received_at ASC', 1),
('rmm-software-change-volume-by-company-company-scoped', 'RMM Software: Change Volume by Company (Last 30 Days) (Company Scoped)', 'Counts of software installs, upgrades and removals detected by RMM Findings per company in the last 30 days. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, SUM(CASE WHEN sc.change_type = ''installed'' THEN 1 ELSE 0 END) AS installed, SUM(CASE WHEN sc.change_type = ''updated'' THEN 1 ELSE 0 END) AS updated, SUM(CASE WHEN sc.change_type = ''removed'' THEN 1 ELSE 0 END) AS removed, COUNT(DISTINCT sc.agent_id) AS devices_changed, MAX(sc.detected_at) AS last_change_at FROM rmm_finding_software_changes sc LEFT JOIN companies c ON c.id = sc.company_id WHERE sc.company_id = {{current.company}} AND sc.detected_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY sc.company_id, c.name ORDER BY COUNT(*) DESC', 1),
('rmm-software-changes-last-30-days-company-scoped', 'RMM Software: Installs and Removals (Last 30 Days) (Company Scoped)', 'Software first seen or removed on a device in the last 30 days from RMM software history, newest first. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, h.name AS application, h.version, h.publisher, CASE WHEN h.removed_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY THEN ''removed'' ELSE ''installed'' END AS change_kind, COALESCE(h.removed_at, h.first_seen_at) AS changed_at FROM rmm_device_software_history h JOIN rmm_agents ag ON ag.id = h.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.company_id = {{current.company}} AND (h.first_seen_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY OR h.removed_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY) ORDER BY changed_at DESC', 1),
('rmm-software-chocolatey-version-gaps-company-scoped', 'RMM Software: Chocolatey Packages Behind the Catalogue (Company Scoped)', 'Installed applications matched to a Chocolatey package whose installed version differs from the latest version in the Chocolatey catalogue. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT s.name AS application, m.package_id, p.version AS catalogue_version, s.version AS installed_version, COUNT(DISTINCT s.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id JOIN rmm_chocolatey_software_matches m ON m.name = s.name JOIN rmm_chocolatey_packages p ON p.package_id = m.package_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND s.version IS NOT NULL AND s.version <> p.version GROUP BY s.name, m.package_id, p.version, s.version ORDER BY devices DESC, application', 1),
('rmm-software-devices-with-application-company-scoped', 'RMM Software: Devices With an Application (Company Scoped)', 'Every device with a matching application installed. Clone and replace "Chrome" in the filter with the application to find. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, s.name AS application, s.version, s.publisher, s.install_date, s.source, ag.last_seen_utc FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id LEFT JOIN companies c ON c.id = ag.company_id LEFT JOIN assets a ON a.id = ag.asset_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND s.name LIKE ''%Chrome%'' ORDER BY company, device, application', 1),
('rmm-software-most-installed-company-scoped', 'RMM Software: Most Installed Applications (Company Scoped)', 'Applications from RMM software inventory ranked by the number of devices they are installed on, with version and company spread. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT s.name, MAX(s.publisher) AS publisher, COUNT(DISTINCT s.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies, COUNT(DISTINCT s.version) AS distinct_versions, MAX(s.version) AS highest_version FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' GROUP BY s.name ORDER BY devices DESC, s.name', 1),
('rmm-software-version-drift-company-scoped', 'RMM Software: Applications Running Multiple Versions (Company Scoped)', 'Applications installed in more than one version across active devices, with the number of devices on each version. Company scoped: limited to the company the report is run for.', 'RMM Inventory and Software', 'SELECT s.name, COALESCE(s.version, ''unknown'') AS version, COUNT(DISTINCT s.agent_id) AS devices, COUNT(DISTINCT ag.company_id) AS companies FROM rmm_device_software s JOIN rmm_agents ag ON ag.id = s.agent_id WHERE ag.company_id = {{current.company}} AND ag.status = ''active'' AND s.name IN ( SELECT s2.name FROM rmm_device_software s2 JOIN rmm_agents ag2 ON ag2.id = s2.agent_id WHERE ag2.company_id = {{current.company}} AND ag2.status = ''active'' GROUP BY s2.name HAVING COUNT(DISTINCT s2.version) > 1) GROUP BY s.name, s.version ORDER BY s.name, devices DESC', 1),
('rmm-schedules-company-scoped', 'RMM Scripts: Scheduled Script Overview (Company Scoped)', 'Scheduled scripts with scope, cron, run-as account, next and last run and the last run summary. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT sch.name, COALESCE(c.name, ''All companies'') AS company, s.name AS script, sch.cron, sch.timezone, sch.target_mode, sch.run_as, CASE WHEN sch.is_enabled = 1 THEN ''enabled'' ELSE ''disabled'' END AS state, sch.next_run_at, sch.last_run_at, sch.last_run_summary FROM rmm_schedules sch LEFT JOIN rmm_scripts s ON s.id = sch.script_id LEFT JOIN companies c ON c.id = sch.company_id WHERE COALESCE(sch.company_id, {{current.company}}) = {{current.company}} ORDER BY state DESC, sch.next_run_at', 1),
('rmm-script-run-outcomes-30-days-company-scoped', 'RMM Scripts: Run Outcomes by Script (Last 30 Days) (Company Scoped)', 'Script runs in the last 30 days per script with completed, failed, timed-out, expired/cancelled counts, success rate and average duration. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT r.script_name, r.language, COUNT(*) AS runs, SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN r.status = ''failed'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN r.status = ''timed_out'' THEN 1 ELSE 0 END) AS timed_out, SUM(CASE WHEN r.status IN (''expired'', ''cancelled'', ''aborted'') THEN 1 ELSE 0 END) AS expired_or_cancelled, ROUND(100 * SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN r.status IN (''completed'', ''failed'', ''timed_out'') THEN 1 ELSE 0 END), 0), 1) AS success_percent, ROUND(AVG(CASE WHEN r.started_at IS NOT NULL AND r.completed_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, r.started_at, r.completed_at) END), 0) AS avg_duration_seconds, COUNT(DISTINCT r.agent_id) AS devices, MAX(r.queued_at) AS last_queued_at FROM rmm_script_runs r WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY r.script_name, r.language ORDER BY runs DESC', 1),
('rmm-script-runs-by-source-daily-company-scoped', 'RMM Scripts: Daily Run Volume by Source (Last 30 Days) (Company Scoped)', 'Script runs per day over the last 30 days split by source: manual, schedule, onboarding, patch, ticket, check, event log and result rule. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT DATE(r.queued_at) AS day, r.run_source, COUNT(*) AS runs, SUM(CASE WHEN r.status = ''completed'' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN r.status IN (''failed'', ''timed_out'') THEN 1 ELSE 0 END) AS failed FROM rmm_script_runs r WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY day, r.run_source ORDER BY day, r.run_source', 1),
('rmm-script-runs-by-technician-company-scoped', 'RMM Scripts: Runs by Technician (Last 30 Days) (Company Scoped)', 'Manually requested script runs per technician in the last 30 days, with the number of scripts, devices and companies touched. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT TRIM(CONCAT(COALESCE(us.first_name, ''''), '' '', COALESCE(us.last_name, ''''))) AS technician, us.email, COUNT(*) AS runs, COUNT(DISTINCT r.script_name) AS scripts, COUNT(DISTINCT r.agent_id) AS devices, COUNT(DISTINCT r.company_id) AS companies, SUM(CASE WHEN r.status IN (''failed'', ''timed_out'') THEN 1 ELSE 0 END) AS failed, MAX(r.queued_at) AS last_run_at FROM rmm_script_runs r JOIN users us ON us.id = r.requested_by_user_id WHERE r.company_id = {{current.company}} AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY GROUP BY r.requested_by_user_id, us.first_name, us.last_name, us.email ORDER BY runs DESC', 1),
('rmm-script-runs-failed-last-7-days-company-scoped', 'RMM Scripts: Failed and Timed-Out Runs (Last 7 Days) (Company Scoped)', 'Script runs that failed or timed out in the last 7 days with device, exit code, error message and how the run was started. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, r.script_name, r.status, r.exit_code, r.error_message, r.run_source, r.run_as, r.queued_at, r.completed_at FROM rmm_script_runs r LEFT JOIN rmm_agents ag ON ag.id = r.agent_id LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN assets a ON a.id = r.asset_id WHERE r.company_id = {{current.company}} AND r.status IN (''failed'', ''timed_out'') AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 7 DAY ORDER BY r.queued_at DESC', 1),
('rmm-script-runs-in-flight-company-scoped', 'RMM Scripts: Queued and Running for Over an Hour (Company Scoped)', 'Script runs still queued, dispatched or running more than an hour after they were queued, oldest first. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT c.name AS company, COALESCE(a.name, ag.hostname) AS device, r.script_name, r.status, r.run_source, r.queued_at, r.dispatched_at, r.started_at, r.expires_at, TIMESTAMPDIFF(MINUTE, r.queued_at, UTC_TIMESTAMP()) AS minutes_waiting, ag.last_seen_utc FROM rmm_script_runs r LEFT JOIN rmm_agents ag ON ag.id = r.agent_id LEFT JOIN companies c ON c.id = r.company_id LEFT JOIN assets a ON a.id = r.asset_id WHERE r.company_id = {{current.company}} AND r.status IN (''queued'', ''dispatched'', ''running'') AND r.queued_at < UTC_TIMESTAMP() - INTERVAL 1 HOUR ORDER BY r.queued_at ASC', 1),
('rmm-scripts-library-usage-company-scoped', 'RMM Scripts: Library Usage (Last 90 Days) (Company Scoped)', 'Every active script in the library with its scope, platforms, timeout, run count and last run in the last 90 days; unused scripts are listed first. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT s.name, s.folder, s.language, COALESCE(c.name, ''All companies'') AS company, s.platforms_json AS platforms, s.default_timeout_seconds, CASE WHEN s.allow_parallel = 1 THEN ''yes'' ELSE ''no'' END AS allow_parallel, COUNT(r.id) AS runs_90_days, MAX(r.queued_at) AS last_run_at, s.updated_at FROM rmm_scripts s LEFT JOIN companies c ON c.id = s.company_id LEFT JOIN rmm_script_runs r ON r.script_id = s.id AND r.company_id = {{current.company}} AND r.queued_at >= UTC_TIMESTAMP() - INTERVAL 90 DAY WHERE COALESCE(s.company_id, {{current.company}}) = {{current.company}} AND s.is_active = 1 GROUP BY s.id, s.name, s.folder, s.language, c.name, s.platforms_json, s.default_timeout_seconds, s.allow_parallel, s.updated_at ORDER BY runs_90_days ASC, s.folder, s.name', 1),
('rmm-ticket-script-runs-company-scoped', 'RMM Scripts: Runs Triggered From Tickets (Last 30 Days) (Company Scoped)', 'Script runs launched by the ticket automation action in the last 30 days, with the ticket, result and when it was reported back. Company scoped: limited to the company the report is run for.', 'RMM Scripts', 'SELECT t.ticket_number, t.subject, c.name AS company, r.script_name, r.status, r.exit_code, tsr.success_status, tsr.created_at, tsr.reported_at FROM rmm_ticket_script_runs tsr JOIN rmm_script_runs r ON r.id = tsr.run_id LEFT JOIN tickets t ON t.id = tsr.ticket_id LEFT JOIN companies c ON c.id = r.company_id WHERE r.company_id = {{current.company}} AND tsr.created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY tsr.created_at DESC', 1),
('shop-orders-by-company-last-30-days-company-scoped', 'Orders: Company Order Volume (Last 30 Days) (Company Scoped)', 'Shop order counts and quantities by company for the last 30 days. Company scoped: limited to the company the report is run for.', 'Shop and Orders', 'SELECT c.name AS company, COUNT(so.id) AS order_count, SUM(so.quantity) AS total_quantity, MIN(so.order_date) AS first_order_at, MAX(so.order_date) AS last_order_at FROM shop_orders so JOIN companies c ON c.id = so.company_id WHERE so.company_id = {{current.company}} AND so.order_date >= (CURRENT_DATE - INTERVAL 30 DAY) GROUP BY c.id, c.name ORDER BY order_count DESC, total_quantity DESC, company ASC', 1),
('shop-quotes-status-and-expiry-company-scoped', 'Quotes: Status and Expiry Overview (Company Scoped)', 'Shop quote counts by status and expiry window to help follow up pending quotes. Company scoped: limited to the company the report is run for.', 'Shop and Orders', 'SELECT sq.status, COUNT(*) AS quote_count, SUM(CASE WHEN sq.expires_at IS NOT NULL AND sq.expires_at < NOW() THEN 1 ELSE 0 END) AS expired_quotes, SUM(CASE WHEN sq.expires_at IS NOT NULL AND sq.expires_at >= NOW() THEN 1 ELSE 0 END) AS unexpired_quotes, SUM(CASE WHEN sq.expires_at IS NULL THEN 1 ELSE 0 END) AS no_expiry_quotes FROM shop_quotes sq WHERE sq.company_id = {{current.company}} GROUP BY sq.status ORDER BY quote_count DESC, sq.status ASC', 1),
('dashboard-global-tickets-by-company-company-scoped', 'Dashboard - Global tickets by company (Company Scoped)', 'Dashboard panel: Global tickets by company. Company scoped: limited to the company the report is run for.', 'Tickets', 'SELECT c.name AS X, COUNT(t.id) AS Y FROM companies c LEFT JOIN tickets t ON t.company_id=c.id WHERE c.id = {{current.company}} GROUP BY c.id,c.name ORDER BY Y DESC', 1),
('stat-strip-admin-tickets-company-scoped', 'Stat Strip - Admin - Ticketing Workspace (Company Scoped)', 'Global non-merged ticket totals by technician status in the ticketing workspace. Company scoped: limited to the company the report is run for.', 'Tickets', 'SELECT status AS ticket_status, COUNT(*) AS tickets FROM tickets WHERE company_id = {{current.company}} AND merged_into_ticket_id IS NULL GROUP BY status ORDER BY ticket_status', 1),
('tickets-open-by-priority-company-scoped', 'Tickets: Open Backlog by Priority (Company Scoped)', 'Open ticket counts grouped by priority so teams can quickly identify urgent backlog trends. Company scoped: limited to the company the report is run for.', 'Tickets', 'SELECT COALESCE(t.priority, ''(unspecified)'') AS priority, COUNT(*) AS open_ticket_count FROM tickets t WHERE t.company_id = {{current.company}} AND t.status IN (''open'', ''in_progress'', ''pending'') GROUP BY COALESCE(t.priority, ''(unspecified)'') ORDER BY open_ticket_count DESC, priority ASC', 1),
('tickets-open-workload-by-technician-company-scoped', 'Tickets: Open Workload by Technician (Company Scoped)', 'Current open ticket count assigned to each technician, including unassigned tickets. Company scoped: limited to the company the report is run for.', 'Tickets', 'SELECT COALESCE(u.email, ''(unassigned)'') AS technician, COUNT(*) AS open_ticket_count FROM tickets t LEFT JOIN users u ON u.id = t.assigned_user_id WHERE t.company_id = {{current.company}} AND t.status IN (''open'', ''in_progress'', ''pending'') GROUP BY u.id, u.email ORDER BY open_ticket_count DESC, technician ASC', 1),
('tickets-parent-child-tasks-company-scoped', 'Tickets: Open Parent Tickets With Linked Child Tickets (Company Scoped)', 'Open tickets that have child tickets (created from tasks or linked as sub-tickets), with how many children are still open. Company scoped: limited to the company the report is run for.', 'Tickets', 'SELECT t.ticket_number, t.subject, c.name AS company, t.status, COUNT(ch.id) AS child_tickets, SUM(CASE WHEN ch.status NOT IN (''resolved'', ''closed'') THEN 1 ELSE 0 END) AS open_children, t.created_at FROM tickets t JOIN tickets ch ON ch.parent_ticket_id = t.id LEFT JOIN companies c ON c.id = t.company_id WHERE t.company_id = {{current.company}} AND t.status NOT IN (''resolved'', ''closed'') GROUP BY t.id, t.ticket_number, t.subject, c.name, t.status, t.created_at ORDER BY open_children DESC, t.created_at', 1),
('tickets-resolution-time-last-30-days-company-scoped', 'Tickets: Average Resolution Time (Last 30 Days) (Company Scoped)', 'Average ticket resolution time in hours for tickets closed in the last 30 days, grouped by company. Company scoped: limited to the company the report is run for.', 'Tickets', 'SELECT COALESCE(c.name, ''(unassigned company)'') AS company, COUNT(*) AS tickets_closed, ROUND(AVG(GREATEST(TIMESTAMPDIFF(MINUTE, t.created_at, t.closed_at), 0)) / 60, 2) AS avg_resolution_hours FROM tickets t LEFT JOIN companies c ON c.id = t.company_id WHERE t.company_id = {{current.company}} AND t.closed_at IS NOT NULL AND t.closed_at >= (CURRENT_DATE - INTERVAL 30 DAY) GROUP BY c.id, COALESCE(c.name, ''(unassigned company)'') ORDER BY avg_resolution_hours DESC, company ASC', 1),
('stat-strip-tray-overview-company-scoped', 'Stat Strip - Tray - Overview (Company Scoped)', 'Active tray devices, seen in the last day, not seen in 30 days, Windows and macOS devices and active deployment URLs. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT COUNT(*) AS devices, SUM(CASE WHEN td.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 1 DAY THEN 1 ELSE 0 END) AS seen_today, SUM(CASE WHEN td.last_seen_utc IS NULL OR td.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 30 DAY THEN 1 ELSE 0 END) AS stale, SUM(CASE WHEN td.os = ''windows'' THEN 1 ELSE 0 END) AS windows, SUM(CASE WHEN td.os = ''darwin'' THEN 1 ELSE 0 END) AS macos, (SELECT COUNT(*) FROM tray_deployment_links l WHERE l.company_id = {{current.company}} AND l.revoked_at IS NULL AND (l.expires_at IS NULL OR l.expires_at > UTC_TIMESTAMP())) AS deployment_urls FROM tray_devices td WHERE td.company_id = {{current.company}} AND td.status = ''active''', 1),
('tray-deployment-builds-failed-company-scoped', 'Tray: Failed Installer Builds (Last 30 Days) (Company Scoped)', 'Tray deployment installer builds that failed in the last 30 days with the company, release and error. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT c.name AS company, l.label, b.release_tag, b.status, b.error, b.requested_at, b.completed_at FROM tray_deployment_builds b JOIN tray_deployment_links l ON l.id = b.deployment_link_id LEFT JOIN companies c ON c.id = l.company_id WHERE l.company_id = {{current.company}} AND b.status = ''failed'' AND b.requested_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY ORDER BY b.requested_at DESC', 1),
('tray-deployment-links-company-scoped', 'Tray: Deployment URL Usage (Company Scoped)', 'Tray deployment URLs per company with downloads, last download, expiry, revocation and the latest installer build status. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT c.name AS company, l.label, l.download_count, l.last_downloaded_at, l.created_at, l.expires_at, l.revoked_at, CASE WHEN l.revoked_at IS NOT NULL THEN ''revoked'' WHEN l.expires_at IS NOT NULL AND l.expires_at < UTC_TIMESTAMP() THEN ''expired'' ELSE ''active'' END AS state, (SELECT b.status FROM tray_deployment_builds b WHERE b.deployment_link_id = l.id ORDER BY b.requested_at DESC, b.id DESC LIMIT 1) AS latest_build_status, (SELECT b.release_tag FROM tray_deployment_builds b WHERE b.deployment_link_id = l.id ORDER BY b.requested_at DESC, b.id DESC LIMIT 1) AS latest_build_release FROM tray_deployment_links l LEFT JOIN companies c ON c.id = l.company_id WHERE l.company_id = {{current.company}} ORDER BY state, company', 1),
('tray-devices-by-version-company-scoped', 'Tray: Devices by App Version and Platform (Company Scoped)', 'Active tray devices by platform and app version with how many checked in within the last day. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT COALESCE(td.os, ''unknown'') AS platform, COALESCE(td.agent_version, ''unknown'') AS tray_version, COUNT(*) AS devices, SUM(CASE WHEN td.last_seen_utc >= UTC_TIMESTAMP() - INTERVAL 1 DAY THEN 1 ELSE 0 END) AS seen_last_24_hours, COUNT(DISTINCT td.company_id) AS companies FROM tray_devices td WHERE td.company_id = {{current.company}} AND td.status = ''active'' GROUP BY td.os, td.agent_version ORDER BY platform, devices DESC', 1),
('tray-devices-not-seen-30-days-company-scoped', 'Tray: Devices Not Seen in 30 Days (Company Scoped)', 'Active tray devices that have not checked in for over 30 days, with the last user, IP and version. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT c.name AS company, td.hostname, td.os, td.os_version, td.agent_version, td.console_user, td.last_ip, td.last_seen_utc, TIMESTAMPDIFF(DAY, td.last_seen_utc, UTC_TIMESTAMP()) AS days_since_seen FROM tray_devices td LEFT JOIN companies c ON c.id = td.company_id WHERE td.company_id = {{current.company}} AND td.status = ''active'' AND (td.last_seen_utc IS NULL OR td.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 30 DAY) ORDER BY td.last_seen_utc ASC', 1),
('tray-enrolments-by-month-company-scoped', 'Tray: Device Enrolments by Month (Company Scoped)', 'Tray devices enrolled per month over the last 12 months by platform. Company scoped: limited to the company the report is run for.', 'Tray', 'SELECT DATE_FORMAT(td.created_at, ''%Y-%m'') AS month, SUM(CASE WHEN td.os = ''windows'' THEN 1 ELSE 0 END) AS windows, SUM(CASE WHEN td.os = ''darwin'' THEN 1 ELSE 0 END) AS macos, SUM(CASE WHEN td.os NOT IN (''windows'', ''darwin'') OR td.os IS NULL THEN 1 ELSE 0 END) AS other, COUNT(*) AS enrolments FROM tray_devices td WHERE td.company_id = {{current.company}} AND td.created_at >= UTC_TIMESTAMP() - INTERVAL 12 MONTH GROUP BY month ORDER BY month', 1),
('account-anonymisation-requests-company-scoped', 'Users: Account Anonymisation Requests (Company Scoped)', 'Account anonymisation (right to erasure) requests with status, who decided, when executed and the support ticket. Company scoped: limited to the company the report is run for.', 'Users and Staff', 'SELECT r.id AS request_id, r.status, r.requested_at, r.scheduled_for, r.decided_at, TRIM(CONCAT(COALESCE(d.first_name, ''''), '' '', COALESCE(d.last_name, ''''))) AS decided_by, r.executed_at, r.completed_at, t.ticket_number AS support_ticket, r.error_message FROM account_anonymisation_requests r JOIN users au ON au.id = r.user_id LEFT JOIN users d ON d.id = r.decided_by LEFT JOIN tickets t ON t.id = r.support_ticket_id WHERE au.company_id = {{current.company}} ORDER BY FIELD(r.status, ''pending'', ''approved'', ''rejected'', ''completed''), r.requested_at DESC', 1),
('dashboard-global-staff-by-company-company-scoped', 'Dashboard - Global staff by company (Company Scoped)', 'Dashboard panel: Global staff by company. Company scoped: limited to the company the report is run for.', 'Users and Staff', 'SELECT c.name AS X, COUNT(s.id) AS Y FROM companies c LEFT JOIN staff s ON s.company_id=c.id WHERE c.id = {{current.company}} GROUP BY c.id,c.name ORDER BY Y DESC', 1),
('dashboard-global-users-company-scoped', 'Dashboard - Global users (Company Scoped)', 'Dashboard panel: Global users. Company scoped: limited to the company the report is run for.', 'Users and Staff', 'SELECT id, email FROM users WHERE company_id = {{current.company}}', 1),
('users-ai-opt-out-and-policy-acceptance-company-scoped', 'Users: AI Opt-Out and Policy Acceptance by Company (Company Scoped)', 'Active users per company with how many opted out of AI features, accepted the legal policies, or have never accepted them. Company scoped: limited to the company the report is run for.', 'Users and Staff', 'SELECT COALESCE(c.name, ''No company'') AS company, COUNT(*) AS users, SUM(us.ai_opt_out) AS ai_opted_out, SUM(CASE WHEN us.policies_accepted_at IS NOT NULL THEN 1 ELSE 0 END) AS policies_accepted, SUM(CASE WHEN us.policies_accepted_at IS NULL THEN 1 ELSE 0 END) AS policies_not_accepted, MAX(us.policies_accepted_version) AS latest_version_accepted FROM users us LEFT JOIN companies c ON c.id = us.company_id WHERE us.company_id = {{current.company}} AND us.is_active = 1 GROUP BY us.company_id, c.name ORDER BY company', 1),
('users-email-domain-distribution-company-scoped', 'Users: Email Domain Distribution (Company Scoped)', 'User count by email domain to help identify tenant segmentation and external account usage. Company scoped: limited to the company the report is run for.', 'Users and Staff', 'SELECT LOWER(SUBSTRING_INDEX(u.email, ''@'', -1)) AS email_domain, COUNT(*) AS user_count FROM users u WHERE u.company_id = {{current.company}} GROUP BY LOWER(SUBSTRING_INDEX(u.email, ''@'', -1)) ORDER BY user_count DESC, email_domain ASC', 1),
('users-inactive-by-company-company-scoped', 'Users: Inactive Accounts by Company (Company Scoped)', 'Inactive user accounts grouped by company to support access cleanup and security reviews. Company scoped: limited to the company the report is run for.', 'Users and Staff', 'SELECT COALESCE(c.name, ''(no company)'') AS company, COUNT(*) AS inactive_user_count FROM users u LEFT JOIN companies c ON c.id = u.company_id WHERE u.company_id = {{current.company}} AND u.is_active = 0 GROUP BY c.id, COALESCE(c.name, ''(no company)'') ORDER BY inactive_user_count DESC, company ASC', 1);
